WordHunterWoW_QuestDataByFlavor = WordHunterWoW_QuestDataByFlavor or {}
WordHunterWoW_QuestDataByFlavor.classic = WordHunterWoW_QuestDataByFlavor.classic or {}
WordHunterWoW_QuestDataByFlavor.classic.enUS = WordHunterWoW_QuestDataByFlavor.classic.enUS or {}
local quests = WordHunterWoW_QuestDataByFlavor.classic.enUS
quests[266] = { title = "Inquire at the Inn", description = "Here is your book, and good luck with your inquiries.\n\nYou might want to expand your search to the inn.  If the person whom you seek spent time in town, then chances are someone saw him there.", objectives = "Search the inn for clues about the shadowy figure.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[267] = { title = "The Trogg Threat", description = "$C, you may or may not be aware of the Trogg threat looming over Dwarven lands.  With the Ironforge Reserve called up to the Alliance Front, we are left with a fraction of the defense forces needed to keep these lands safe.  My regiment is assigned to watch over the Gate here and we cannot leave our post for fear of invasion.\n\nBut we need some pressure put on those damned Troggs lurking in the hills.  If you're up to the task, wage an assault on the Troggs.  Bring me back 8 Trogg Stone Teeth as proof.", objectives = "Bring 8 Trogg Stone Teeth to Captain Rugelfuss in the southern guard tower.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[268] = { title = "Return to Sven", description = "The book you found was only half finished.  I had to leave it at Sven's farm when I fled there...\n\nHere.  Take my completed journal to Sven.  It describes more fully what happened at his farm.\n\nAlthough this journal has been my only company these past weeks, if giving it up keeps me from having to face Sven and his wrath, then I do it willingly!", objectives = "Return to Sven with Jitters' completed journal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[269] = { title = "Seeking Wisdom", description = "Go to the city of Stormwind and speak with Bishop Farthing in the Cathedral of Light.  Give him Jitters' journal and tell him you mean to face Morbent Fel.\n\nAlthough Stormwind has forsaken Darkshire, Farthing is a kind soul and very wise.  He may help you on your quest to save us.\n\nYour mission is perilous, but hurry, $N.  With each passing hour, the shadows of Duskwood grow ever darker.", objectives = "Give Jitters' Completed Journal to Bishop Farthing in Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[270] = { title = "The Doomed Fleet", description = "Years ago, the Third Fleet of Kul'Tiras sunk along the coasts of The Wetlands, an expanse of marsh north of the Dwarven kingdom of Ironforge.  Aboard one ship was a load of Lightforge Iron.\n\nThis metal is precious to us, for items crafted from it strike with holy truth.  If you are to face Morbent Fel, then you will need such a weapon.\n\nGo to Menethil Harbor and speak with my dwarven colleague Glorin Steelbrow.  If that lost metal can be found, he'll know where to look.", objectives = "Go to Menethil Harbor in the Wetlands, and speak with Glorin Steelbrow.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[271] = { title = "Vyrin's Revenge", description = "I don't suppose you'd be interested in a little payback for His Boldness? Daryl does have some skill, it pains me to say.\n\nA year ago, a large bear had been the target of the Farstrider Lodge, but none of the hunters had any luck with him. So, Daryl thought he'd try his hand against him. All he had to show for his effort was that ugly scar over his eye.\n\nKill the bear, and I'm sure even Daryl would be speechless for once.\n\nThe bear, Ol' Sooty, can be found around his lair in the hills over Thelsamar.", objectives = "Kill Ol' Sooty then show your handiwork to Daryl the Youngling at the Farstrider Lodge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[272] = { title = "Trial of the Sea Lion", description = "For the second trial, you'll need the two halves that make the Pendant of the Sea Lion.  One half draws power from the agility of the sea lion aspect, gliding through water; the other draws power from the incredible endurance of the sea lion aspect.  Druids draw on both these traits equally to embody the aspect of their aquatic form.\n\nSpeak with the locals of Moonglade to learn where the parts may lie, and bring both here to join them together.  Once formed, take the pendant to Dendrite Starblaze.", objectives = "Find the Half Pendant of Aquatic Agility and the Half Pendant of Aquatic Endurance.  Speak with the residents of Moonglade to learn clues as to where these items may be located.\n\nForm the Pendant of the Sea Lion from the two pendant halves.  You need to be in proximity of the Shrine of Remulos to do this.\n\nBring the joined pendant to Dendrite Starblaze in the village of Nighthaven, Moonglade.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[273] = { title = "Resupplying the Excavation", description = "It's not too late though, you're welcome to go look for Huldar. He can't have made it very far, strong as they are, Miran and Saean can only move so fast laden down with those barrels.\n\nThey're taking the normal route to the site, leaving south out of town and following the curve of the Loch.\n\nShouldn't have a problem finding them unless they've already gotten there.", objectives = "Speak with Huldar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[274] = { title = "A Dark Threat Looms", description = "This ain't no ordinary blast powder.  Look at the tiny silver crystals.  And the distinct smell!  Why it's clear as daylight that this is Seaforium Powder.  Seaforium is harmless enough.  But once it's wet it could blow Ironforge out of the mountain.\n\nThe chemical reaction can be defused by mixing four components:  lurker venom, crushed Mo'Grosh crystal, a crocolisk tear and this disarming colloid.  Now tell Hinderweir before it's too late!", objectives = "Ashlan Stonesmirk wants you to return to Chief Engineer Hinderweir and inform him of the new discovery.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[275] = { title = "Blisters on The Land", description = "I do not know why, but a festering grows within the Wetlands.  Fen Creepers have risen.  They are diseased, fevered blisters on the land, and for the fever to break they must be dispatched and allowed to settle back into the marshes.\n\nThe Fen Creepers shamble amidst the waterways of the Wetlands.", objectives = "Kill 12 Fen Creepers, then return to Rethiel the Greenwarden in the Wetlands.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[276] = { title = "Tramping Paws", description = "The Mosshide Gnolls have lived in the Wetlands peacefully for many years, but now grow in numbers.  Their feet stamp flat the fen's bushes and flowers, and their foul axes cut too much wood to fuel their fires.\n\nThey are no longer in balance with the land.  For the Wetlands to survive, the Gnolls must be reduced.\n\nKill 15 Mosshide Gnolls and 10 Mosshide Mongrels.  Hunt them to the south, near the Dwarven gate of Algaz.  After you do this, return to me.", objectives = "Kill 15 Mosshide Gnolls and 10 Mosshide Mongrels, then return to Rethiel the Greenwarden in the Wetlands.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[277] = { title = "Fire Taboo", description = "The Mosshides are cutting the trees of the Wetlands, using the trees' flesh to warm themselves with fire.  I will suffer this pain no longer!\n\nRid the Mosshides of their crude flints, the tools they use to make fire.  The flints are borne by all Mosshides except the smaller Mosshide gnolls and Mosshide mongrels.", objectives = "Bring Rethiel the Greenwarden 9 Crude Flints.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[278] = { title = "A Dark Threat Looms", description = "Begin collecting the disarming materials immediately, $N.  Lurker Venom can be found on the indigenous spiders in Loch Modan.  Crocolisk tears are found here in the Loch as well.  But a Mo'Grosh crystal will be very difficult to procure.  The ogres to the northeast mine them but the crystals are a very rare commodity.\n\nWe need to be prepared to defuse a Dark Iron attack!  Return to me once you've collected the needed items and I will prepare the mixture.", objectives = "Chief Engineer Hinderweir wants you to gather Lurker Venom, a Mo'grosh Crystal, and a Crocolisk Tear.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[279] = { title = "Claws from the Deep", description = "Murlocs are crawling out from the deep waters and building their villages on the coastline.  They are harassing our fishers and merchants and must be stopped.\n\nOne of these Murlocs, Gobbler, skulks with other Bluegill Murlocs and harries merchants along the road, always then retreating to the safety of the nearby Murloc hovels.  Our merchants are in jeopardy, and we will pay to secure them.\n\nGobbler prowls the river inlet north of here.  Find him, slay his kin, and bring me his head.", objectives = "Kill 12 Bluegill Murlocs.\n\nSlay Gobbler and take his head.\n\nBring Gobbler's Head to Karl Boran in Menethil Harbor.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[280] = { title = "A Dark Threat Looms", description = "Earlier today I spotted some Dark Iron Insurgents swimming toward the Dam with a large keg.  No Mountaineers were on hand to stop them!  I'm afraid they've planted the Seaforium at the base of the Dam and it could blow at any minute!  Let me combine all these ingredients into the Disarming Mixture.  There we go.\n\nNow I need you to take this mixture and stir it into the keg before it's too late!  Hurry!", objectives = "Chief Engineer Hinderweir wants you to swim down to the base of the dam, locate the powder keg and stir in the Disarming Mixture to prevent an explosion.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[281] = { title = "Reclaiming Goods", description = "Not long ago a merchant vessel, the Blind Princess, was raided by Murlocs.  Although the ship escaped intact, much of its cargo was dragged overboard by the creatures, including a very valuable statuette of Terenas Menethil.  We want that statuette recovered.\n\nSearch the coastal Murloc hovels for crates, barrels and other evidence of lost cargo.  Find the Menethil Statuette and return it to me.", objectives = "Search the crates and barrels at the coastal Murloc camps.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[282] = { title = "Senir's Observations", description = "I was planning on sending my apprentice to my brother Senir with my report, but I would feel much better were it placed in more... reliable hands. That is, of course, if you wouldn't mind?\n\nHmm... you'll have to take the tunnel to get to Kharanos.\n\nSpeak with Mountaineer Thalos before going through the tunnel. It's completely infested with troggs now.\n\nFollow the road back to Anvilmar, then keep heading east to the tunnel, Thalos is stationed nearby.", objectives = "Speak with Mountaineer Thalos.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[283] = { title = "A Dark Threat Looms", description = "The keg fizzles slightly.", objectives = "The Disarming Mixture seemed to take effect.  Return to Chief Engineer Hinderweir to report the good news.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[284] = { title = "The Search Continues", description = "You thoroughly search this cluster of Murloc hovels, and find no trace of the Menethil Statuette.\n\nPerhaps one of the two nearby hovels to the north and northeast will have more clues.", objectives = "Search for the Menethil Statuette.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[285] = { title = "Search More Hovels", description = "This grouping of Murloc hovels, after a thorough inspection, reveals nothing.\n\n...but you're certain that the next clue you find will be fruitful.\n\nOne of the hovels to the north must have the Menethil Statuette!", objectives = "Continue searching the Murloc hovels for the Menethil Statuette.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[286] = { title = "Return the Statuette", description = "After pulling the barrel free from the muck and opening it, a silvery figurine is found packed in fine straw.  It depicts a young, long-haired Paladin with hammer upraised.\n\nThis must be the Menethil Statuette!  You must now return it to Karl Boran in Menethil Harbor.", objectives = "Bring Karl Boran the Menethil Statuette.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[287] = { title = "Frostmane Hold", description = "I'm behind on my report, and could use your help, $n. I just managed to find where the trolls are holed up, but I saw so many trolls, I was afraid to go in.\n\nHere's what I need... Go down to the cave, poke around inside, kill a few of the trolls, then come back here.\n\nTake the road north out of Kharanos, when you get to the bridge, follow the frozen river west until you reach Iceflow Lake. You'll find Brewnall Village on the west bank. The Hold is southwest of the village.", objectives = "Explore Frostmane Hold, and kill 5 Frostmane Headhunters for Senir Whitebeard in Kharanos.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[288] = { title = "The Third Fleet", description = "I was once First Mate on the Wave Mistress, ship-of-the-line in the Kul Tiras Third Fleet.  The Doomed Fleet.  Doomed, for on its last voyage the fleet was attacked  by Red Dragons.  Dragons controlled by Orcs!\n\nWe didn't stand a chance against that dragonfire...and our fleet was burned and sunk off this here coast.  I'm the sole survivor of those poor vessels...\n\n...Oh, my head hammers and pounds!  I'll need a fresh drink if I'm to get a handle on this hangover and continue my tale.", objectives = "Buy First Mate Fitzsimmons a Flagon of Mead.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[289] = { title = "The Cursed Crew", description = "<Bolstered, Fitzsimmons continues his tale...>\n\nI am the sole survivor of the ill-fated Third Fleet of Kul Tiras, wrecked off the coast to the north.  But although I'm the only member of the fleet still breathing, I'm not the only one still walking about!  For on one of our ships was hidden a great, and terrible treasure, and the eerie power of it keeps the souls of my brothers trapped within the ships' rotting hulls.\n\nBut if you can free some of my brothers, then perhaps you can break their curse.", objectives = "Kill 13 Cursed Sailors, 5 Cursed Marines and First Mate Snellig.  Bring Snellig's Snuffbox to First Mate Fitzsimmons in Menethil Harbor.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[290] = { title = "Lifting the Curse", description = "To break the curse and free all of my brethren, the...thing...stowed on my ship must be retrieved and cleansed!  I don't know what it was, but I do know that it was stored securely in the ship's strongbox, which Captain Halyndor lorded over.\n\nMy old captain is still in my dreams.  I know he walks my doomed ship, the Intrepid.  Get the key from him, and use it to open the Intrepid's strongbox.\n\nThen, after you have the cursed thing, bring it to the priest Glorin Steelbrow in town.", objectives = "Get the Intrepid Strongbox Key from Captain Halyndor.\n\nUse the key to open the Intrepid's Locked Strongbox.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[291] = { title = "The Reports", description = "Excellent! Take my report to Senator Barin Redstone. He's a sour type, so don't let his less-than-sunny disposition get to you. He's in Ironforge, in the chamber where King Magni holds court.\n\nDon't know the way to Ironforge? Take the road out of Kharanos north, cross the bridge, then follow the road east--there are large banners flanking the road--up the mountainside.\n\nBy the way, if you might avoid mentioning how you assisted me? Can't let them think I'm not working hard out here, you know?", objectives = "Deliver Senir's report to Senator Barin Redstone in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[292] = { title = "The Eye of Paleth", description = "Opening the chest reveals a blackened orb, pulsing with an eerie light.  It is the treasure of which Fitzsimmons spoke: a Cursed Eye of Paleth.\n\nTake the Cursed Eye of Paleth to the dwarven priest Glorin Steelbrow, in Menethil Harbor.  Ask him how to remove the Eye's curse.", objectives = "Bring the Cursed Eye of Paleth to Glorin Steelbrow.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[293] = { title = "Cleansing the Eye", description = "I can't lift the curse from the Eye of Paleth.  The Eyes were crafted by Human Priests, so you'll have to go to Stormwind to find someone who can help you.  Speak with Archbishop Benedictus.  He is head of the Cathedral of Light in Stormwind.  He can help.\n\nI hope, for your sake.", objectives = "Bring Archbishop Benedictus the Cursed Eye of Paleth.  Benedictus is in the Cathedral of Light, in the city of Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[294] = { title = "Ormer's Revenge", description = "The situation is severe, that much is for sure.  When we uncovered these bones it attracted the Raptors.  These filthy beasts killed my brethren and trapped me, Merrin and the poor Prospector up here.\n\nHelp clear the Wetlands of these Raptors, $N.  Mottled Raptors and Mottled Screechers are just West of the bluff there.  Kill 10 of each, if you can.\n\nThat will be a good start to the vengeance I have planned for them.", objectives = "Ormer Ironbraid at the Whelgar Excavation Site wants you to kill 10 Mottled Screechers and 10 Mottled Raptors.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[295] = { title = "Ormer's Revenge", description = "Now it's time to really make those dreaded Raptors regret their blood-thirst.  Just down below there are scores of Mottled Scytheclaws and Mottled Razormaws.  Make those rotten creatures pay by slaying 10 of each!", objectives = "Ormer Ironbraid wants you to kill 10 Mottled Scytheclaw raptors and 10 Mottled Razormaw raptors then return to him at the Whelgar Excavation Site.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[296] = { title = "Ormer's Revenge", description = "While you were down there I happened to notice that one of those beasts stood out from the rest.  He was bigger and more menacing.  I bet he's the one who led the others here to cause the disruption to the dig site.\n\nI ask of you now one final task, $N.  See to it that Sarltooth is brought to justice.  And considering the gravity of his crimes, justice in this case means death!  Bring me one of his talons as proof of his death.", objectives = "Ormer Ironbraid at the Whelgar Excavation Site wants you to kill Sarltooth and return to him with one of his talons once the task is fulfilled.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[297] = { title = "Gathering Idols", description = "Recently, just before the Troggs surfaced within the site, we had uncovered a large number of strange, carved idols.  But we didn't have the chance to study them, for soon after their discovery the Troggs chased us away from the ruins!  And those idols have a strange effect on the Troggs.  It makes them go berserk!\n\nBring me 8 idols - I want to study them, and I want them out of Trogg hands!  You can find the idols on the Troggs infesting the site.", objectives = "Bring Magmar Fellhew 8 Carved Stone Idols.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[298] = { title = "Excavation Progress Report", description = "I need a progress report sent to Thelsamar - a progress report, and a restatement of my request for more blastpowder!  Here's the report.  Take it to Jern Hornhelm.  He's our local contact in Thelsamar.\n\nIt's not a difficult task, but it must be done.", objectives = "Bring Ironband's Progress Report to Jern Hornhelm in Thelsamar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[299] = { title = "Uncovering the Past", description = "Just before the invasion I uncovered a large tablet called the Goaz Stone.  The translated text breaks off in 4 places.  The text speaks of a \"divine plan\" and a \"doomed prophecy.\"\n\nI fear we are running out of time.  I am too old to go down and brave those beasts.  But you are strong.\n\nScour the excavation site and uncover the 4 missing tablet fragments: Ados, Modr, Golm and Neru.  Search for them in ancient artifacts or where the soil is loose.  Bring them to me so I can begin unlocking the mystery!", objectives = "Prospector Whelgar wants you to scour the excavation site in search of the 4 missing tablet fragments: Ados, Modr, Golm and Neru.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[301] = { title = "Report to Ironforge", description = "We'll need approval to get Ironband more blastpowder. You'll have to take his report to the Explorers' League headquarters in Ironforge.\n\nHere's the report. Give it to Prospector Stormpike, and don't forget to duck after you deliver it. Stormpike is hotheaded, and he won't be happy to hear of Ironband's slow progress at the site.\n\nYou'll find Stormpike in the Assembly of Explorers.", objectives = "Take Ironband's Progress Report to Prospector Stormpike.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[302] = { title = "Powder to Ironband", description = "If Ironband still needs blastpowder, then by Magni he'll have it!  I sent the approval on ahead with a messenger to Jern Hornhelm in Thelsamar.  He'll prepare the powder and other supplies to take to Ironband.\n\nAnd one more thing: I want you to personally see that the shipment of powder reaches its destination.  The last one didn't, so keep your mind sharp and your eyes open.", objectives = "Speak with Jern Hornhelm in Thelsamar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[303] = { title = "The Dark Iron War", description = "War rages both home and abroad.  While mighty Dwarven soldiers give their lives in far off territories in the name of the Alliance, our own lands fall prey to the evil deeds of the Dark Iron Dwarves.  They laid waste to the Thandol Span.  Dun Modr fell soon after.\n\nWe need you to gather force and push the front back.  If you can kill 15 Dark Iron Dwarves, 5 Tunnelers, 5 Saboteurs and 5 Demolitionists, the reserve might arrive in time to finish the drive.\n\nNow make haste!", objectives = "Motley Garmason at Dun Modr wants you to kill 15 Dark Iron Dwarves,  5 Dark Iron Tunnelers, 5 Dark Iron Saboteurs and 5 Dark Iron Demolitionists.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[304] = { title = "A Grim Task", description = "Many of my soldiers died in the battle of Dun Modr.  My own brother perished when the West Bridge over the Thandol Span was destroyed.  Aye, the Dark Iron dwarves are a devilish breed.  From what Roggo was able to gather, the leader of this band of thugs in the Wetlands is a warlock named Balgaras the Foul.  He is quite a coward however.  He sends his soldiers to do his bidding but stays elusive, avoiding danger.\n\nIf you can find the spineless scum, slay him and bring me his ear.  I will reward you, $c.", objectives = "Kill Balgaras the Foul and bring his ear to Longbraid the Grim outside of Dun Modr.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[305] = { title = "In Search of The Excavation Team", description = "Oh my, you must be the scout Longbraid said he would send!  You cannot imagine how worried I have been.\n\nMy wife, Merrin, has been sending me letters each week for the past month.  She is part of the Whelgar Excavation team.  But it has been nearly two weeks since her last correspondence.  Surely something is wrong!\n\nLongbraid said that he would send a scout to check up on things if we did not hear from the team soon.  I assume that scout is you, $N.  Find Merrin at the excavation site to the east!", objectives = "Tarrel Rockweaver wants you to travel to the Excavation Site and contact Merrin Rockweaver.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[306] = { title = "In Search of The Excavation Team", description = "It was horrible!  We were uncovering some rare artifacts and we began to discover these large bones.\n\nBefore we knew what was happening, these Mottled Raptors overwhelmed the dig site.  Many lives were lost.\n\nOrmer here -- so brave -- saved the Prospector and me.  He defended us as we ran for shelter.  Now we are trapped.  And our hard work lies in ruin.\n\nHere, take this note back to my sweet Tarrel.  It will explain the situation to him.", objectives = "Return to Tarrel Rockweaver with Merrin's note.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[307] = { title = "Filthy Paws", description = "The Silver Stream Mine to the east ran dry long ago.  It was converted by the Miners' League into a storage depot, but now Kobolds have moved in, putting their filthy paws on good, Dwarven tools!\n\nWe'll root out those vermin soon enough, but the League wants someone to get their gear out of the mine before we warriors tromp in there and break things.  It'll be a tough delve - you might want cohorts at your side.\n\nThe gear is stored in Miners' League Crates throughout the mine.  Good luck.", objectives = "Go to the Silver Stream Mine and collect 4 loads of Miners' Gear.\n\nReturn to Mountaineer Stormpike.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[308] = { title = "Distracting Jarven", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[309] = { title = "Protecting the Shipment", description = "Ready to go, $n?\n\nFirst, we need to get this powder to Ironband. It'll be a lot for me to carry, and these parts can get dangerous -- and who knows what else the Dark Irons might have in store for me.\n\nI'll feel a lot better with you coming along.", objectives = "Ensure Miran and the shipment arrive at the excavation site, then inform Prospector Ironband.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[310] = { title = "Bitter Rivals", description = "I have to admit, those Thunderbrews make some good drinks.  But they need to learn that theirs isn't the only decent brew!  Maybe you can help me teach them that lesson...\n\nHere, take this barrel of Barleybrew Scalder.  Sneak into the basement of the Thunderbrew Distillery in Kharanos and switch it with one of their barrels of Thunder Ale.  Then we'll see how their patrons like my brew over theirs!\n\nAnd if the barrels are guarded, then you might have to distract the guard ...", objectives = "In the basement of the Thunderbrew Distillery in Kharanos, replace a barrel of Thunder Ale with a Barrel of Barleybrew Scalder.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[311] = { title = "Return to Marleth", description = "Having inserted a barrel of Marleth's Scalder in the Kharanos Distillery's cellar, you grab a barrel of Thunder Ale as proof of the deed...", objectives = "Bring the barrel of Thunder Ale to Marleth Barleybrew at the Brewnall Village.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[312] = { title = "Tundra MacGrann's Stolen Stash", description = "I had a month's worth of dried meats salted and locked away for the cold season.  Kept it locked so the bears wouldn't get it!  But while I was off hunting deer, that beast, Old Icebeard, made off with the meat locker.  He won't be able to smash through that Thorium though.  But I'll starve if I can't get my meats back.\n\nYou seem a bit more stealthy than me.  Perhaps you can retrieve my stash?  I'll never make it in and out of that cave fast enough with this bum leg of mine.", objectives = "Retrieve Tundra MacGrann's dried meats from the stolen meat locker in Old Icebeard's cave.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[313] = { title = "The Grizzled Den", description = "Driving a Siege Engine isn't for everyone.  It takes an iron grip and nerves of steel...lucky I have both!  How about you?  How's your mettle?  Want to prove it to me?\n\nWell...I'm looking to make my engine, Trollplow, a little more cozy.  How about you get me a heap of Wendigo Manes from the Grizzled Den, west of Kharanos.  Those manes would make a great rug for Trollplow's inside deck!", objectives = "Gather 8 Wendigo Manes and bring them to Pilot Stonegear.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[314] = { title = "Protecting the Herd", description = "We heard the cries in the middle of the night.  Then this morning, sure enough, the herd was missing two rams.  That dastardly beast known as Vagash has been preying on our livelihood.  With most of King Magni's army off in distant lands fighting with the Alliance, there is no one to keep Vagash at bay.\n\nPerhaps you are brave enough to seek out the beast and slay him.  Bring me one of his fangs and I will reward you.  Vagash lurks just above the ranch here, but be warned, he is deadly.", objectives = "Rudra Amberstill wants you to slay Vagash and bring his fang to her at the Ram ranch.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[315] = { title = "The Perfect Stout", description = "I'm on a quest, a quest to make the perfect stout.  I know I can do it -- brewing's in my blood.  I just need to find the right recipe...\n\nThe Frostmane trolls grow a plant, shimmerweed, high up in the hills to the east.  They use it in their strange, tribal rituals.  We dwarves haven't found much use for it, but it has a unique taste...and I want to experiment with it in my brews!\n\nGet me some shimmerweed from Frostmane seers, or swipe it from the trolls' shimmerweed baskets.", objectives = "Bring 6 Shimmerweeds to Rejold Barleybrew in the Brewnall Village.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[317] = { title = "Stocking Jetsteam", description = "I'm preparing to start a mission for the Siege Brigade.  It's a long one, and I need to stock Jetsteam with a month's worth of supplies.  So while Steelgrill is working on my tank, can you do some hunting for me?\n\nI'll need some fur for bedding, and boar meat for food.  You can get meat from boars and fur from the bears... you can find them both in the snow fields south of the Grizzled Den.", objectives = "Gather 4 Chunks of Boar Meat and 2 Thick Bear Furs, and deliver them to Pilot Bellowfiz at Steelgrill's Depot.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[318] = { title = "Evershine", description = "Rejold Barleybrew experiments with his brews.  Some of them taste good, some bad, and some...well, some will lay all but the stoutest dwarf flat.\n\nHe lives at Brewnall Village, west of Kharanos, and one of his drinks, Evershine, is what I want.  It'll help keep me warm while I'm on the cold road.\n\nAnd...the blessed stuff burns so hot I can throw it in Jetsteam's furnace for a burst of power!  That little tactic has gotten me out of more than one tight spot.", objectives = "Get a cask of Evershine from Rejold Barleybrew in Brewnall Village.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[319] = { title = "A Favor for Evershine", description = "I have a cask of Evershine handy, but...can you do me a favor?  Brewnall village could use a hand against the wild animals that wander the nearby snows.  Sometimes they wander close.\n\nWe're not afraid of these bears and cats and boars - no self respecting dwarf would be - but if you can take care of those animals for us, then we'd have more time for our crafting and brewing.", objectives = "Kill 6 Ice Claw Bears, 8 Elder Crag Boars, and 8 Snow Leopards, and then return to Rejold Barleybrew in Brewnall Village.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[320] = { title = "Return to Bellowfiz", description = "Here's your cask of Evershine, $N.  And again, thank you for the hunting earlier.", objectives = "Give the cask of Evershine to Pilot Bellowfiz at Steelgrill's Depot.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[321] = { title = "Lightforge Iron", description = "The shipwrecks off the shore here are the doomed Third Fleet of Kul'Tiras, burned and sunk by Red Dragons during the last Great War.\n\nThe Fleet hailed from Lordaeron, but one ship, an Elvish Destroyer: Flying Osprey, was with it.  It was shipping a load of Lightforge Iron and joined the Third Fleet for protection.  Ironic that it sunk to the same dragons...\n\nEnough history.  The Flying Osprey is wrecked to the south of Menethil Harbor.  If you find the Lightforge Iron there, bring it to me.", objectives = "Search the wreckage of The Flying Osprey in the Wetlands.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[322] = { title = "Blessed Arm", description = "There is a dwarven weaponsmith in the Dwarven District of Stormwind who can craft with lightforge iron.  His name is Grimand Elmore.\n\nI've packed the iron you found into a crate.  Take it to Grimand and tell him your tale.  I'm sure he'll oblige someone on a quest such as yours, and craft for you a weapon - a weapon to give even Morbent Fel worry!", objectives = "Take the Crate of Lightforge Ingots to Grimand Elmore in Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[323] = { title = "Proving Your Worth", description = "Morbent Fel is a necromancer, and an ally to the dark riders.  I would pit you against the power of Morbent Fel, but I will not send you against that vile fiend without first knowing your strength.\n\nYou have already proven your bravery to me, but if you truly wish to face the necromancer, then you must now prove your skill against his minions.", objectives = "Kill 15 Skeletal Raiders, 3 Skeletal Healers and 3 Skeletal Warders, and then return to Sven.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[324] = { title = "The Lost Ingots", description = "Having grabbed the single lightforge ingot from the waterlogged chest, it is clear that murlocs have stolen the rest.  Hunt the murloc raiders near the Flying Osprey wreckage for the lost lightforge iron.", objectives = "Gather 5 Lightforge Ingots, then return to Glorin Steelbrow in the Wetlands.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[325] = { title = "Armed and Ready", description = "Here is the weapon against the fiend of which you spoke.  You're all ready, $N.  Best of luck to you, and I look forward to your tale of glory!", objectives = "Bring Morbent's Bane to Sven in Duskwood.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[328] = { title = "The Hidden Key", description = "Although no mention of Private Thorsen is found in these records, hidden within the binding of one of Herod's ledger books is a small, brass key.\n\nAnd after further study of his notes, a few references to a \"secure strongbox\" are contained among various papers.  The box is somewhere within the Stockpile - the cavern complex at the back of Kurzen's Compound.\n\nIf this secure strongbox is found, and the small brass key can open it, then perhaps the mystery behind Thorsen's detection will be revealed.", objectives = "Use the Small Brass Key to open Bookie Herod's Strongbox.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[329] = { title = "The Spy Revealed!", description = "Among the valuables of the strongbox is a muddy, scribbled note.  Although barely legible, it looks to be an itinerary for Private Thorsen.  It details his patrol routes, who he speaks with and how he spends his time with the rebels.  It's signed with only one letter: -M.\n\nBut whoever wrote this note must have stayed very close to Thorsen.  Whoever wrote this note is the traitor within the rebel camp.", objectives = "Take the Muddy Note to Lieutenant Doren at the Rebel Camp.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[330] = { title = "Patrol Schedules", description = "The note you gave me is signed with an \"-M\"...I don't know what that could mean.\n\nBut...the note also says this person shared patrol routes with Thorsen last week.  So whoever shared patrol with Thorsen last week must be the traitor!\n\nGo to Corporal Sethman.  He handles the patrol schedules and can tell you who was with Thorsen.", objectives = "Speak with Corporal Sethman.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[331] = { title = "Report to Doren", description = "Did Lieutenant Doren want you to report back to him with that patrol information?", objectives = "Speak with Lieutenant Doren.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[332] = { title = "Wine Shop Advert", description = "If you talk to anyone about wine, then you know we Gallinas sell the best wine in Stormwind.  And we're not far, still in the Trade District along the city's lovely canals.\n\nHere, take this pamphlet.  Bring it to my sister Suzetta at our shop for a complimentary bottle of our famous pinot noir.  You won't regret it!", objectives = "Go to the Gallina Winery, and bring Suzetta Gallina the Wine Ticket for a free bottle of wine.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[333] = { title = "Harlan Needs a Resupply", description = "We've been doing a lot of business lately.  It seems like everyone is buying armor and sturdy clothes.  Almost like they expect a cold, harsh season ahead...\n\nBut those are future worries.  My worry today is that I'm running out of knitted clothing to sell.  I need another load from our supplier.\n\nIf you can take this request to Rema Schneider at the Canal Tailor and Fit Shop, I'd be most grateful.", objectives = "Go to the Canal Tailor Shop and bring Rema Schneider the Cloth Request from Harlan Bagley.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[334] = { title = "Package for Thurman", description = "My son Thurman is an apprentice at the Larson Clothiers, in the Mage's Quarter.  He was in a hurry today and forgot his shears and needles.  I know a great $C like you must have important tasks at hand, but without his tools Thurman can't do his apprentice work!\n\nPlease, $N.  Can you take my son's sewing kit to him?  Larson Clothiers is one of two clothing shops in the Mage's Quarter - it's the one deeper in, near the Mage's Tower.", objectives = "Go to the Larson Clothiers in the Stormwind Mage Quarter, and give Thurman Schneider his Sewing Kit.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[335] = { title = "A Noble Brew", description = "Lord Wishock is causing quite a stir amongst the House of Nobles.  He was made aware of our little \"establishment\" down here and is lobbying for a full investigation.  I have a plan to keep Wishock \"preoccupied,\" but I'll need your help. \n\nThere is a flower growing in the Garden of Stalvan on the outskirts of Darkshire.  This small white flower is known as the Tear of Tilloa.  I will also need a Musquash Root, found only at the very base of the falls far beneath the Stonewrought Dam in the Wetlands.", objectives = "Zardeth the Black Claw wants you to bring him a Tear of Tilloa from Darkshire and a Musquash Root from the Wetlands.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[336] = { title = "A Noble Brew", description = "Lord Wishock, like all men, has his weaknesses.  His happens to be a fondness for liquor.  The hypocrisy is astounding.  The trite fool spends his days trying to shut down our little \"tavern\" while his nights are spent upstairs, running up a bill he never pays.  Well, let's see how Wishock likes this special brew I have prepared for him:  Black Claw stout.  It's got quite a kick, $n.\n\nTake it to him and see how he likes it.  Most likely the old fool is milling about the Hall of Petitioners.", objectives = "Take the Black Claw Stout to Lord Wishock in the Hall of Petitioners.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[337] = { title = "An Old History Book", description = "Although the cover of this book is marred by scratches and caked with mud, the words \"The History of Stormwind\" can still be read along its spine.  Upon opening the book, the seal of the Stormwind Library is clearly stamped on the book's first page.\n\nIt looks like someone checked out this book, and never returned it...", objectives = "Return the book: The History of Stormwind, to the Stormwind Library.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[338] = { title = "The Green Hills of Stranglethorn", description = "Master Nesingwary will be so upset if he finds out!\n\nHe trusted me to proofread the manuscript of his novel, The Green Hills of Stranglethorn.  Everything was going well, but a large gust of wind blew through the camp and scattered the pages everywhere!\n\nI was able to gather most of the pages but many are still strewn about the jungle.  Collect the pages to complete each of the four chapters.\n\nI will help you organize them.  Return the chapters to me once you have all four.", objectives = "Collect the missing pages from The Green Hills of Stranglethorn manuscript.  Once all four chapters are complete, return them to Barnil.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[339] = { title = "Chapter I", description = "Chapter I was quite riveting!  Master Nesingwary sets the backdrop for the story and makes mention of his hunting companions, including me! \n\nBut that's besides the point.  Let me see which pages are still missing.  It seems pages 1, 4, 6 and 8 are still out there somewhere in the jungle!", objectives = "Bring pages 1, 4, 6, and 8 of Nesingwary's The Green Hills of Stranglethorn to Barnil Stonepot in order to complete Chapter I.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[340] = { title = "Chapter II", description = "Chapter II was chock full of exciting tales of panther and tiger hunting.  I could just kick myself for letting the pages blow away! \n\n It seems I was able to recover all of the pages with the exception of pages 10, 11, 14, and 16.", objectives = "Bring pages 10, 11, 14 and 16 of Nesingwary's The Green Hills of Stranglethorn to Barnil Stonepot in order to complete Chapter II.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[341] = { title = "Chapter III", description = "Chapter III was my favorite.  It tells of Sir Erlgadin and Lady Rouack's first kill with a dwarven rifle.  And the end of Chapter III, why, such a cliffhanger!  \n\nLooks to me as though we still need pages 18, 20, 21 and 24 to finish the chapter.  Those pages are out there somewhere. . .", objectives = "Bring pages 18, 20, 21and 24 of Nesingwary's The Green Hills of Stranglethorn to Barnil Stonepot in order to complete Chapter III.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[342] = { title = "Chapter IV", description = "Ah Chapter IV; the big finale!  And what an ending it was! \n\nWe are only missing three pages for this chapter.  We need pages 25, 26 and 27 to put Chapter IV back together.", objectives = "Bring pages 25, 26, and 27 of Nesingwary's The Green Hills of Stranglethorn to Barnil Stonepot in order to complete Chapter IV.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[343] = { title = "Speaking of Fortitude", description = "I'm giving a speech on the Fortitude of the Spirit, and I'd like to recite passages from a particular book on metallurgy - \"The Stresses of Iron.\"  A copy of this book should be in the Royal Library, within Stormwind Keep.  Can you retrieve it for me?  If so, then may the blessings of the Light be with you!\n\nThe Royal Library is very large, but the head librarian, Milton Sheaf, knows each shelf like it was his own son.  Speak to him, he'll retrieve the book for you.", objectives = "Go to the Royal Library in Stormwind Keep and speak with Milton Sheaf.  He can find for you the book on metallurgy that Brother Kristoff needs for his speech.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[344] = { title = "Brother Paxton", description = "The Stresses of Iron?  Yes, I know the book.  Quite a good one, written by the Dwarven miner Margulf Blaggon a few decades ago.  He spent most his time deep in the mountains of Khaz Modan, digging ore.  Smart fellow!\n\nBut where was I?  Oh yes, the Stresses of Iron!  I'm afraid the book was moved to the Northshire Abbey.  The caretaker of the Abbey's library, Brother Paxton, wanted to make a copy of the book for his own shelves.\n\nBut that was months ago.  I wonder why it's taking him so long...", objectives = "Speak with Brother Paxton in the Northshire Abbey.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[345] = { title = "Ink Supplies", description = "I've been meaning to finish my copy of The Stresses of Iron, but...\n\nWell you see, I make my own ink for books I copy.  It's my own recipe; it doesn't run or smear, and it dries very quickly  Unfortunately, it dries too quickly!  My last batch dried up before I could finish the copying job, and I haven't had the chance to make more ink!\n\nTo make more I need Rethban Iron Ore from the Redridge Mountains.  Foreman Oslow in Lakeshire is my usual supplier.", objectives = "Speak with Foreman Oslow in Lakeshire and ask him for Rethban Iron Ore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[346] = { title = "Return to Kristoff", description = "Now that I've finished copying the book, here's the original Stresses of Iron.  Thank you for your patience, and if you see Milton please tell him I'm sorry for the long delay.", objectives = "Return to Brother Kristoff in the Cathedral Square.  Give him the book The Stresses of Iron.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[347] = { title = "Rethban Ore", description = "Rethban Ore is named after the man who first found it, Bart Rethban.  When smelted it's not as strong as iron, but its ore has a dark, flat color that some scribes use in their dyes.  It can be found in the Rethban Caverns, north of here.\n\nWe usually have some in stock, but we're too busy preparing for Orc attacks to gather any.  And besides...Redridge Gnolls are now living in the Rethban Caverns and their Drudgers are gathering the ore themselves.\n\nSo if you need some, you'll have to get it yourself.", objectives = "Gather 5 loads of Rethban Ore and bring it to Brother Paxton in the Northshire Library.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[348] = { title = "Stranglethorn Fever", description = "Sick...so...very s-s-sick....\n\n...have contracted Stranglethorn Fever...deadly v-v-virus...\n\n...only cure...is...is...to eat the heart of M-m-m-m-mokk the Savage...elusive white beast...\n\n...Witch doctor Unbagwa...only one who can s-s-summon....\n\n...seek Unbagwa in hidden cave on southern cape...\n\n...hurry...dying...dying....", objectives = "Seek out Witch Doctor Unbagwa and have him summon Mokk the Savage.  Bring the Heart of Mokk to Fin Fizracket.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[349] = { title = "Stranglethorn Fever", description = "temp text 02 - description", objectives = "temp text 02 - log", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[350] = { title = "Look to an Old Friend", description = "That Marzon would be contacting a member of the Defias and have ties to Lescovar...\n\nHaving killed VanCleef and Thredd, it would be hard to see Lescovar brought to proper justice, as your evidence is nothing without their testimonies. That is not even considering the fact that Lescovar is a noble and well connected. It effectively makes him above the law.\n\nYou'll need other help. I loathe to do so, but there is someone I know that will aid us. You'll find Trias in the Trade District of the city.", objectives = "Speak to Elling Trias in Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[351] = { title = "Find OOX-17/TN!", description = "You have uncovered some sort of strange, egg-shaped device made from metal.  Fiddling with one of its knobs springs the egg to life, as it opens up into some sort of gnomish robotic contraption!  A voice from inside the robotic egg crackles to life.\n\n\"The name's Oglethorpe, and my homing robot has gone missing!  I will reward you for its recovery!  Please take this beacon to the robot.  Excellent, I now have computed the coordinates for you!  It crashed near the Gaping Chasm in Tanaris!\"", objectives = "Bring the distress beacon to Oglethorpe's homing robot.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[353] = { title = "Stormpike's Delivery", description = "The Stormpikes are a respected dwarven clan, and are well known for their fine and discerning tastes.  So it's no wonder that Gringer Stormpike, a Mountaineer of Ironforge, commissioned me to craft him a weapon.\n\nThe weapon is finished, but... Mountaineer Stormpike is far away, in distant Loch Modan.  If you plan on traveling to the north, can you deliver this package to him?\n\nMy last message from Mountaineer Stormpike said he's stationed at the northern guard tower in Loch Modan.", objectives = "Deliver the Package for Stormpike to Mountaineer Stormpike in Loch Modan.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[354] = { title = "Deaths in the Family", description = "The Agamand family was the most prosperous family in Tirisfal Glades.  I used to work their mills...before the Plague.\n\nWhen the Scourge first came, the Agamands fortified their home and convinced those in their employ to remain and help them defend.  We were fools, but at least we were loyal fools.\n\nThe Agamands, in their pride, doomed us to undeath.  And now they are minions of the Scourge!\n\nServe the Forsaken by defeating the Agamands who fell to the Plague.  Serve me by bringing me their remains.", objectives = "Bring Gregor's Remains, Nissa's Remains and Thurman's Remains to Coleman Farthing in Brill.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[355] = { title = "Speak with Sevren", description = "You have given me the remains of the Agamands, and satisfied my desire for revenge.  But the Agamand Mills hold a threat to all the Forsaken, not just to me.\n\nI have spoken to Magistrate Sevren of your exploits against the Agamands, and he wishes to speak with you.", objectives = "Speak with Magistrate Sevren in Brill.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[356] = { title = "Rear Guard Patrol", description = "The defenders on The Bulwark protecting Tirisfal from the Plaguelands are on constant alert.  But sometimes Scourge will slip past them.\n\nOur success at the Bulwark depends on a one-front battle - we cannot allow an attack from the rear, nor can we allow our defenders' supply line to be cut.\n\nAssist the Bulwark.  Patrol east and slay any Scourge you find.  Spend particular effort at the Balnir Farmstead to the east.  It has become a haven for interloping Scourge.", objectives = "Kill 8 Bleeding Horrors and 8 Wandering Spirits, then report back to Linnea at her camp.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[357] = { title = "The Lich's Identity", description = "There is a lich who dwells on the island in Brightwater Lake to the north.  Although he is a free-willed Forsaken, he believes all other Undead are Scourge slaves and has his minions attack anyone who approaches him.\n\nBut because he is Forsaken, the Queen will want him.  And if he is skilled in Necromancy, then his knowledge would be...quite useful to us.\n\nTo discover his identity and his talents, I must see his spellbook.  Steal into his camp and acquire it, then return to me.", objectives = "Bring the Lich's Spellbook to Bethor Iceshard in the Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[358] = { title = "Graverobbers", description = "The Mass Graves, southwest of Garren's Haunt to the north, were made to accommodate the...impressive...number of deaths Tirisfal suffered when the Plague first came.  \n\nThe bodies in these graves have so far been spared an undeath, but the Scourge now send Rot Hide Gnolls to gather the corpses and use them to bolster their armies.  This cannot be allowed!\n\nYour task is twofold: slay the Rot Hides at the Mass Grave and Garren's Haunt, and gather from them the Embalming Ichor that gives them life.", objectives = "Kill Rot Hide Graverobbers and Rot Hide Mongrels.  \n\nBring 8 Embalming Ichors to Magistrate Sevren in Brill.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[359] = { title = "Forsaken Duties", description = "I need a fresh report from our Deathguard waystation to the east.\n\nI must know if more Scourge forces have slipped past The Bulwark and into Tirisfal.  Our vigilance on the border to the Plaguelands must be maintained - we can't let the Scourge get a stronger foothold here!\n\nTravel south along the road, then east at the fork to the waystation.  Speak with Deathguard Linnea.  She has the information I need.", objectives = "Speak with Deathguard Linnea.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[360] = { title = "Return to the Magistrate", description = "Now return to Magistrate Sevren with the information I gave you.  He'll want it as soon as possible, so be swift.\n\nAnd if you see any Scourge on your way back, take them down - we can't let them wander our lands unchallenged.", objectives = "Return to Magistrate Sevren in Brill.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[361] = { title = "A Letter Undelivered", description = "This is a letter written by Thurman, the eldest son of Gregor Agamand.  It is addressed to an Yvette Farthing, though it does not appear to have reached her...", objectives = "Find Yvette Farthing, and deliver to her the letter from Thurman Agamand.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[362] = { title = "The Haunted Mills", description = "Devlin Agamand was the younger of two sons in the Agamand family, and in life the two could not be more different.  Thurman was tall and gentle while his younger brother was weak and sharp tongued.\n\nWhen Agamand Mills fell to the Plague, I was not surprised to hear that Devlin was quick to succumb.  His mad chattering can still be heard near the road leading to the Agamand Mills.\n\nI'm collecting the remains of the Agamands, and I want poor Devlin.  Find him, destroy him, and bring me his bones.", objectives = "Slay Devlin Agamand, and bring Devlin's Remains to Coleman Farthing in Brill.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[363] = { title = "Rude Awakening", description = "About time you woke up. We were ready to toss you into the fire with the others, but it looks like you made it.\n\nI am Mordo, the caretaker of the crypt of Deathknell. And you are the Lich King's slave no more.\n\nSpeak with Shadow Priest Sarvis in the chapel at the base of the hill, he will tell you more of what you must know.", objectives = "Speak with Shadow Priest Sarvis.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[364] = { title = "The Mindless Ones", description = "We Forsaken are at war with the Lich King's army of the Scourge: necromantically raised armies of the undead, foul beasts of the north, and tormented spectres.\n\nThe northern part of the village has become overrun with the Mindless Ones, and they must be destroyed. Destroy them, show them no mercy, our former brothers and sisters as they might be. The Fallen are nothing but The Lich King's slaves.", objectives = "Shadow Priest Sarvis wants you to kill 8 Mindless Zombies and 8 Wretched Zombies.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[365] = { title = "Fields of Grief", description = "What have we here?  You look like a fledgling $c.  If you hope to prove yourself to The Dark Lady, you need to learn the ways of The Forsaken.\n\nTo the west you'll find a farm.  Humans infest the land like mold on a rotting corpse.  And worse yet, the Scarlet Crusade patrols nearby from their tower.  Teach those scum a lesson and steal 10 of their precious pumpkins.\n\nOnce you have 10, take them to Apothecary Johaan in Brill.", objectives = "Steal 10 pumpkins from the farm to the west, just north of Deathknell and take them to Apothecary Johaan in Brill.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[366] = { title = "Return the Book", description = "Long ago Gunther and I, along with the now Scourge Necromancer Thule Ravenclaw, were friends and students within the Kirin Tor - a society of mages in Dalaran.\n\nGunther and I both fell to the Plague, but I thought he either remained dead, or was raised into the ranks of the Lich King.  It is good to know he is free.\n\nWe must have him.  I have placed a spell on his book that, when he sees it, will show him that I too am free of the Lich King.  After knowing this, it is my hope that he will join us.", objectives = "Return Gunther's Spellbook to him, on the island of Gunther's Retreat.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[367] = { title = "A New Plague", description = "Lady Sylvanas has called upon the Royal Apothecary Society. The Dark Lady believes our knowledge coupled with the newfound magic will provide the key to Arthas's demise.  She has challenged us to concoct a new plague, a plague deadlier than any ailment on Azeroth. This new disease will bring Arthas's Scourge Army to ruin.\n\nMy studies show that the blood of beasts might prove to be the key. Bring to me 5 vials of darkhound blood so I can test my theory. ", objectives = "Apothecary Johaan in the town of Brill wants you to collect 5 Vials of Darkhound Blood.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[368] = { title = "A New Plague", description = "While you were collecting samples for me, my experiments led me to realize that more reagents will be required for this new disease to spread properly. Poisoning some hapless victim is child's play. Plaguing an entire world proves to be a bit more complicated.\n\nI will need 5 Vile Fin Scales from Murlocs in the vicinity.  You will find the creatures along the coast to the north or to the west.", objectives = "Apothecary Johaan of the town of Brill needs 5 Vile Fin Scales from Murlocs in Tirisfal Glades.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[369] = { title = "A New Plague", description = "While you were out gathering, I uncovered some old text in one of my tomes that indicates that an ancient plague wiped out thousands of innocent victims.  Later it was discovered that the deadly agent in the plague was preserved through the venom of Night Web Spiders.\n\nBring me some venom from a Vicious Night Web Spider to complete this experiment.  I want to see if the contagious element from the venom will work with my new concoction.  Rumor has it the spiders can be found in Eastern Tirisfal Glades.", objectives = "Apothecary Johaan in the town of Brill wants you to bring him 4 samples of venom from a Vicious Night Web Spider.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[370] = { title = "At War With The Scarlet Crusade", description = "The strategic documents from Executor Arren contain all the details we need to wipe the human infestation from the lands.  According to the information, The Scarlet Crusade has assigned Captain Perrine and a brigade to the ruined tower southwest of Brill.\n\nKill Perrine along with 3 Zealots and 3 Missionaries and report back to me.", objectives = "Executor Zygand in Brill wants you to kill Captain Perrine, 3 Scarlet Zealots and 3 Scarlet Missionaries.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[371] = { title = "At War With The Scarlet Crusade", description = "We are still at war and the Scarlet Crusade grows in strength.  The report Executor Arren sent me indicates Scarlet Crusaders have been raiding from the ruined tower in southeastern Tirisfal near the Balnir Farmstead under the command of Captain Vachon.\n\nKill Vachon along with 5 Scarlet Friars. It should prove to be a devastating blow to the Crusade!", objectives = "Executor Zygand in Brill has commissioned you to slay Captain Vachon and 5 Scarlet Friars.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[372] = { title = "At War With The Scarlet Crusade", description = "Scarlet Crusaders have been raiding from the ruined tower in northern Tirisfal, past Faol's Rest.  According to the information we have, a ruthless commander named Captain Melrache is in charge of this evil crew.\n\nI am entrusting you now with a special and dangerous mission.  Slay Melrache and his two bodyguards, in the name of The Dark Lady.", objectives = "Executor Zygand in the town of Brill wants you to assassinate Captain Melrache and his two bodyguards.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[373] = { title = "The Unsent Letter", description = "Searching Edwin VanCleef's person, you discover, among other things, an unsent letter. It is addressed to Baros Alexston, the City Architect of Stormwind, City Hall, Cathedral Square.\n\nIt appears to be recently written and sealed.", objectives = "Deliver the Letter to the City Architect to Baros Alexston in Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[374] = { title = "Proof of Demise", description = "Executor Zygand tells me you've been out killing Scarlet Crusaders. Tirisfal Glades is crawling with them.\n\nVarimathras, lieutenant to The Dark Lady, is seeing to it personally that the scum of Azeroth, the Human race, gets wiped into oblivion. Here in Tirisfal Glades we face a particularly annoying breed of humans: The Scarlet Crusade.\n\nVenture forth and wage an offensive on the Scarlet Crusade, $c. Bring me back 10 Scarlet Insignia Rings as proof of your loyalty to Varimathras and The Dark Lady.", objectives = "Bring 10 Scarlet Insignia Rings to Deathguard Burgess in Brill.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[375] = { title = "The Chill of Death", description = "It's so cold, now.  The Plague of Undeath crawls through my veins like an icy serpent.  The Mindless State will be upon me soon.  But no doomed destiny will prevent me from serving our Dark Lady.  When the call arose I sewed body bags for the fallen soldiers of Sylvanas's mighty army.\n\nNow my hands shake from the chill.  If you would bring me five Duskbat Pelts and some Coarse Thread I could sew myself a blanket.  Help me, $N, so that I can continue to serve the cause.", objectives = "Bring five Duskbat Pelts and some Coarse Thread to Gretchen Dedmar in Brill.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[376] = { title = "The Damned", description = "My duties include tending to our wounded warriors, tailoring armor and clothes, and assisting Shadow Priest Sarvis with whatever else he might need.\n\nFrom the look of it, you'll be enlisted in his service also... hunting the Mindless Ones, if I know his mind. Well, if you'd like to stay in one piece--and I've no doubt you do--perhaps I can help. I'm running out of paws and wings, and if you bring me some, I'll find some armor for you. You'll find a good number of wolves and bats to the south.", objectives = "Novice Elreth requires 6 Scavenger Paws and 6 Duskbat Wings.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[377] = { title = "Crime and Punishment", description = "As if the neglect for the residents of Duskwood was not bad enough, now the House of Nobles spits in the eye of the Darkshire Council with their decision to imprison Dextren Ward in Stormwind rather than behead the villain as per Lord Ebonlocke's sentence.\n\nWard was caught selling bodies from the cemetery to Morbent Fel, a crime punishable by death.  Yet Stormwind claims Ward as their prisoner.\n\nAssassinate Ward in The Stormwind Stockade - bring me his hand - and I shall reward you.", objectives = "Councilman Millstipe of Darkshire wants you to bring him the hand of Dextren Ward.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[378] = { title = "The Fury Runs Deep", description = "You have proven your loyalty to King Magni, $c.  And your hatred for the Dark Iron scum is as great as my own.\n\nThere is a task I wish to complete myself but I am bound by honor to stay with Longbraid.  But Roggo has gathered intelligence that proves Kam Deepfury was a conspirator in the attack on the Thandol Span.  It was by Deepfury's planning that Longbraid lost his kin.\n\nDeepfury is being held for political reasons in the Stormwind Stockade.  I want him dead, $N.  For Longbraid!  Bring me his head!", objectives = "Motley Garmason wants Kam Deepfury's head brought to him at Dun Modr.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[379] = { title = "Slake That Thirst", description = "You want a power source.  I can help you with that.  Know what I want?  I want something to drink!  Bring me five Wastewander Water Pouches, and I'll give you the 4711-FTZ.\n\nNow... guess where you can find Wastewander Water Pouches!  Why don't you walk up to one of the Wastewander nomads to the east of here and ask them for one.  Let me know how that works out for you.", objectives = "Bring 5 Wastewander Water Pouches to Chief Engineer Bilgewhizzle in Gadgetzan.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[380] = { title = "Night Web's Hollow", description = "One of our greatest struggles is obtaining the natural resources we need to survive. Gold was scarce even in the height of the Alliance's power.\n\nThere is a gold mine to the northwest that has been overrun with spiders. We need gold from the mine, but we can't very well get it while the spiders are crawling around in there. I've not much manpower to commit to the task, so we'll just have to do it little by little.\n\nGet up there and see what you can do for us, $n.", objectives = "Executor Arren wants you to kill 10 Young Night Web Spiders and 8 Night Web Spiders.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[381] = { title = "The Scarlet Crusade", description = "You'll be happy to know we appear to be making progress in the mine, thanks in no small part to your efforts.  We can now turn our eyes to other concerns.\n\nMy scouts have reported that a detachment of the Scarlet Crusade is setting up a camp southeast of here. The Scarlet Crusade is a despicable organization that hunts us, and they will not rest until every undead--Lich King's Scourge or no--is destroyed. We must strike first!\n\nBe careful, their unholy zeal makes them dangerous adversaries.", objectives = "Bring Executor Arren 12 Scarlet Armbands from Scarlet Converts and Scarlet Initiates.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[382] = { title = "The Red Messenger", description = "Reports from my superiors in Brill indicate that an agent of the Scarlet Crusade was dispatched from the Scarlet Monastery and sent here to Deathknell. According to the reports, the messenger possesses important information on his person. I do not have further details, but whatever it is, we must have it!\n\nYou're the most qualified person I have to send, $n. Find that messenger and bring me whatever information you can find.", objectives = "Kill Meven Korgal, the messenger, at the Crusader camp, then return any information you find to Executor Arren.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[383] = { title = "Vital Intelligence", description = "These will need to be taken to my superior, Executor Zygand, in Brill. With this information, we'll be able to deal a decisive blow to the Scarlet Crusade. Your services have been useful here in Deathknell, but I need someone to deliver this to Zygand, and I believe he'll be able to find you more appropriate work.\n\nTake the road north out of Deathknell. Soon after entering Tirisfal proper, you'll hit a crossroads. Take the eastern fork, and keep going east. You'll pass Cold Hearth Manor along the way.", objectives = "Deliver the Scarlet Crusade Documents to Executor Zygand in Brill.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[384] = { title = "Beer Basted Boar Ribs", description = "Nothing my tavern patrons enjoy more than some Beer Basted Boar Ribs!  Only problem is, the local trapper who used to bring me supplies enlisted in the King's Army to help with the war on the Alliance front. \n\nMaybe you can help me out?  If you bring me six crag boar ribs and a Rhapsody Malt from the tavern here, I'll give you the family recipe for my famous Beer Basted Boar Ribs, not to mention a free sample!  The secret's in the Malt!", objectives = "Ragnar Thunderbrew in Kharanos wants 6 Crag Boar Ribs and a mug of Rhapsody Malt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[385] = { title = "Crocolisk Hunting", description = "Many a hunter is attracted to Loch Modan to hunt our famous crocs. There are always merchants who seek out crocolisk skins for clothing items or armor, and there are also some who enjoy the taste of their meat.\n\nWe do some trade in this, but not a huge amount, as the crocolisks are ferocious and have entrenched themselves on the islands in the Loch. But don't let me dissuade you, it's quite an experience, wrestling with the jaws of the beasts.\n\nWhy, this one time...", objectives = "Get 5 pieces of Crocolisk Meat and 6 Crocolisk Skins for Marek Ironheart at the Farstrider Lodge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[386] = { title = "What Comes Around...", description = "Targorr the Dread served under Gath'Ilzogg as supreme Executioner.  His methods were ruthless, even by filthy orc standards.  Men who fought bravely to defend the Kingdom were tortured on his whim.  Now he is being held in the Stormwind Stockade, sentenced to die.  Yet something is amiss.  One of the bureaucratic nobles put a hold on his execution.  I am sure foul play is in the works.\n\nPut an end to Targorr the Dread, $N.  Travel to The Stockade and behead him before trickery is upon us.", objectives = "Bring the head of Targorr the Dread to Guard Berton in Lakeshire.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[387] = { title = "Quell The Uprising", description = "The uprising must be quelled!  I need your assistance.  If word gets out that the prison is overrun I will lose my job!  This is a case of foul play if I've ever seen one.  But what's important now is forcing these prisoners into submission for the safety of Stormwind.\n\nThe punishment for insurgency is death.  Kill some of these deviants!  That ought to get things under control.", objectives = "Warden Thelwater of Stormwind wants you to kill 10 Defias Prisoners, 8 Defias Convicts, and 8 Defias Insurgents in The Stockade.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[388] = { title = "The Color of Blood", description = "Bitterness flows through my veins like a cold river.  My grandson, Mac, was such a good boy.  A mere 14 years old.  When the army was sent off to the front, Mac took up arms to defend the city.  He was a guard in The Stockade, where the Defias gang is locked up.  Mac reprimanded some of the prisoners for tearing their wool blankets to make scarves, a symbol of their gang.  For that Mac was stabbed in the back.\n\nI want revenge.  Bring me 10 of their precious Wool Bandanas.  They are the color of blood.", objectives = "Nikova Raskol of Stormwind wants you to collect 10 Red Wool Bandanas.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[389] = { title = "Bazil Thredd", description = "VanCleef and I were members of the Stonemasons Guild. Our main project was to rebuild Stormwind after the War.\n\nWhen we had finished our duties, we were cheated. The nobles refused to pay us for our work. Some of the more senior of the Stonemasons were offered governmental jobs, but VanCleef refused it out of loyalty to all the Stonemasons. He led a riot and left the city, swearing revenge.\n\nHis lieutenant, Bazil Thredd, might know more about VanCleef's plans. He's being held prisoner in the Stockade.", objectives = "Speak with Warden Thelwater in the Stockade.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[391] = { title = "The Stockade Riots", description = "Let's get one thing straight, $N: I don't trust you. But, with the situation as it is, you probably won't make a difference.\n\nSo here's how it's going to be: go down there and have your talk with Thredd. If you're really on our side, then kill him and bring me his head when the job's done. And if it turns out you're on his side, and don't come out... when we find you, you'll die along with the rest of the maggots.", objectives = "Kill Bazil Thredd and bring his head back to Warden Thelwater at the Stockade.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[392] = { title = "The Curious Visitor", description = "During the first years of Thredd's imprisonment, he never had any visitors. I figured that he was no longer of use to the Brotherhood, so they abandoned him.\n\nAnyway, a few months ago, that all changed; he started to get regular visits... once, maybe twice a week. It was a strange man--the quiet type. I had my suspicions, but all his papers checked out.\n\nHis documents claimed his name was Maelik; here's his description. I don't think he'll be coming to visit Thredd anymore.", objectives = "Bring the Sealed Description of Thredd's Visitor to Baros Alexston in Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[393] = { title = "Shadow of the Past", description = "I really haven't a clue, $N. There is someone else who might be able to help you, and it so happens that he owes me a favor for--well, let's not get into that. Master Mathias Shaw of SI:7 can be found in the barracks in Old Town. Shaw has his thumb on most of the shady, or underhanded dealings of the city.\n\nIf anyone knows, it'd be him.", objectives = "Bring the Sealed Description of Thredd's Visitor to Master Mathias Shaw in Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[394] = { title = "The Head of the Beast", description = "Find Shaw in Old Town. Let him know that the Lescovar threat has been dealt with and about your involvement in the Lord's plots against the city. I'm sure he'll be proud to have another hero among Stormwind's citizens.\n\nHe'll more than likely send you off to meet with the Prince or some other noble. Don't let it get to your head, $N. The nobles can think they rule the city all they want, but some things remain out of their hands.", objectives = "Speak to Mathias Shaw in Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[395] = { title = "Brotherhood's End", description = "Ah, I almost forgot. Alexston came while you were away, he wished to speak with you. No doubt he wishes to report the goings-on of the Defias Brotherhood to the nobles.\n\nA bit of advice, $N: if anyone should ask, I would provide all details but that it was your hand that slew Lescovar. Trust me. I am... acquainted... with the ways of such things.\n\nAnd as far as Trias goes, well, speak to no one of him... ever... if you can help it.", objectives = "Speak with Baros Alexston in Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[396] = { title = "An Audience with the King", description = "I have prepared a report for the King. I believe you should be the one to deliver it to him, along with an account of your findings. Do not worry, there is no doubt that he will commend you for doing your duty to the people of Stormwind.\n\nYour audience is scheduled soon, so you'd best hurry, it's a bit of a ways to Stormwind Keep.", objectives = "Deliver Baros Alexston's report on the Defias Brotherhood to King Varian Wrynn in Stormwind Keep.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[397] = { title = "You Have Served Us Well", description = "I hear Lord Wishock enjoyed his beverage.  \n\nYou have served us well, $N.  The Warlocks of Stormwind will be able to practice our ways without disturbance, thanks to you.  For your efforts, I have prepared a special gift for you.  Speak with my servant, Zggi, and claim your reward.", objectives = "Speak with Zggi, the servant of Zardeth the Blackclaw, to claim your reward.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[398] = { title = "Wanted: Maggot Eye", description = "Wanted: Maggot Eye!\n\nA foul beast, even by Gnoll standards, Maggot Eye has been sentenced to death for his crimes against The Forsaken.  This despicable villain has been stealing corpses for use by the Lich King's army.  Maggot Eye was last seen pillaging the lands near Garren's Haunt to the north of Brill.\n\nThe town of Brill hereby offers a reward to the capable soul who can carry out the execution.  Show Executor Zygand the villain's paw once the deed is done.\n\nMercy is for the weak.", objectives = "Kill Maggot Eye and return to Executor Zygand in Brill with his paw for a reward.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[399] = { title = "Humble Beginnings", description = "It seems an eternity since I was a boy working the farm in Westfall. They say you can never go back, and it's true. Doubly true in my case, my family's home has been burned down and taken over by thieves.\n\nI have spoken with my father about the fate of some of my possessions, including my first compass. He was unable to save them. However, he also says that they should be hidden away on the farm.\n\nYou'll find the Alexston Farmstead west of Sentinel Hill. Perhaps you could go and retrieve it for me?", objectives = "Go to Baros Alexston's house in Westfall and search for his compass, then return it to him in Cathedral Square of Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[400] = { title = "Tools for Steelgrill", description = "Beldin Steelgrill owns the local mechanic shop, and he's the best siege engine tech there is!  But he's not forgiving to his tools.  I swear he almost breaks more arclight spanners than we can supply him with!\n\nWe just filled his last order for tools.  If you deliver it to him I'm sure he'll make it worth the effort.\n\nHis shop, Steelgrill's Depot, is just northeast of Kharanos.  And it's a local haunt for veteran siege engine pilots, so keep your ears open for opportunities while you're there.", objectives = "Deliver Steelgrill's Tools to Beldin Steelgrill.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[401] = { title = "Wait for Sirra to Finish", description = "I'm almost finished translating that note.  If you come back in a few moments I should be done.", objectives = "Wait a moment, then speak with Sirra Von'Indi again.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[403] = { title = "Guarded Thunderbrew Barrel", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[404] = { title = "A Putrid Task", description = "Scourge have trickled into Tirisfal Glades and have infested the area west of Brill, near the old bridge.\n\nGo there and beat back the rotting dead and ravaged corpses you find.  Scatter their bones and bring back their putrid claws, and the Deathguards will reward you.", objectives = "Bring 7 Putrid Claws to Deathguard Dillinger in Brill.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[405] = { title = "The Prodigal Lich", description = "Bethor Iceshard, a high-ranking and powerful mage in the Undercity to the south, commands me to send him an agent with proven worth against the Scourge.  You, $N, will be that agent.\n\nPresent these orders to Bethor.  He will then instruct you on your mission.  I don't know its details, but it deals with recruiting a wayward Lich.  And it will be dangerous.\n\nSo ready yourself, $C.  You must not fail.\n\nYou may find Bethor in the Magic Quarter of the Undercity.", objectives = "Present Sevren's Orders to Bethor Iceshard in the Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[407] = { title = "Fields of Grief", description = "Harmless pumpkins, right?  Or so it would seem.  If we are to defeat Arthas's advances from the North and the Human infestation from the South we need to start realizing the full potential of our gift of undeath.\n\nWith a little ingenuity a simple pumpkin becomes an agent for our Dark Lady.  This pumpkin, laced with my latest formula, will prove to be quite a treat.\n\nYet another Scarlet Zealot has been captured and is being kept in the cellar of the Gallow's End Tavern.  Take this pumpkin to the fool.", objectives = "Take the Laced Pumpkin to the Captured Scarlet Zealot who is being held in the cellar of the Gallow's End Tavern.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[408] = { title = "The Family Crypt", description = "The Agamand Mills area has become a foothold for the Scourge.  Their strongest point is the Agamand Family Crypt where their local military leader, a skeleton named Captain Dargol, has headquartered.  With Necromancy he has raised the ancestors of the Agamands and plans to use them against us.\n\nThis cannot pass, and you must stop it.  Travel to the Agamand Family Crypt and defeat the raised Agamand ancestors.\n\nAnd, bring me the skull of Captain Dargol.", objectives = "Kill 8 Wailing Ancestors and 8 Rotting Ancestors.\n\nKill Captain Dargol, and bring his skull to Magistrate Sevren in Brill.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[409] = { title = "Proving Allegiance", description = "You say you are not bound by the will of the Lich King, and the enchantment Bethor placed upon my book corroborates this.  But before I believe you I must have proof that you are enemy to the Scourge.\n\nThere is an old, bloody altar just off the southern coast of this island.  it is used by a powerful Scourge agent, Lillith Nefara.\n\nTake a Candle of Beckoning from this crate here.  Light it on the altar and Lillith will awake.  Destroy Lillith, and I will believe you are the Lich King's foe.", objectives = "Obtain a Candle of Beckoning.\n\nSummon Lillith Nefara and kill her.\n\nReturn to Gunther on his island.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[410] = { title = "The Dormant Shade", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[411] = { title = "The Prodigal Lich Returns", description = "Take this Nether Gem to my old comrade Bethor.  It will let us communicate ... and I have much to tell him.", objectives = "Bring the Nether Gem to Bethor Iceshard in the Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[412] = { title = "Operation Recombobulation", description = "Upon further analysis of the Gnomeregan situation, it would appear as though we not only failed to eradicate the troggs but we also happened to turn most of the gnomish race into horrific, mindless, evil-doing leper gnomes.\n\nOzzie and I plan to reverse the horrible leper effect with our latest invention: The Recombobulator.  The machine is almost complete but we are in dire need of some Restabilization Cogs and Gyromechanic Gears.  Retrieve some from the leper gnomes out front of Gnomeregan for us.", objectives = "Bring Razzle Sprysprocket in Kharanos 8 Restabilization Cogs and 8 Gyromechanic Gears.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[413] = { title = "Shimmer Stout", description = "I'd like my brother Wellart to try my new Shimmer Stout.  He's a Mountaineer stationed in the southern guard tower, one of two towers on the border to Loch Modan.\n\nHe may not be a brewer like the rest of us Barleybrews, but he loves his drinks and I know he'll like this one.\n\nCan you bring him this Barrel of Shimmer Stout for me?", objectives = "Take the Barrel of Shimmer Stout to Mountaineer Barleybrew.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[414] = { title = "Stout to Kadrell", description = "I've been drinking more of that Shimmer Stout my brother made - it's great stuff!  I want a fellow Mountaineer to try it.  His name's Kadrell, and he's usually patrolling the road through Thelsamar in Loch Modan.\n\nTo get to Thelsamar, go southeast through the tunnel, then turn northeast when the path forks into a road.  Follow that road straight into Thelsamar.\n\nGive Mountaineer Kadrell this cask of Shimmer Stout and see what he thinks!", objectives = "Take the Cask of Shimmer Stout to Mountaineer Kadrell.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[415] = { title = "Rejold's New Brew", description = "Rejold Barleybrew at Brewnall Village has been asking for you.\n\nHe wants to talk to you about a new drink he's been brewing...said something about you helping him with it.  You might want to head back to Brewnall Village and see what he has to say.\n\nThere could be some free booze in it for you...", objectives = "Speak with Rejold Barleybrew.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[416] = { title = "Rat Catching", description = "We have a real infestation problem to the west.  Tunnel rat kobolds have moved into the foothills, setting up dens and fouling our land with their filth!\n\nWe want them eliminated.  Hunt them, bring me their ears and earn their bounty.\n\nYou can find tunnel rat kobolds and their dens west of Thelsamar, littered along the mountainside.", objectives = "Bring 12 Tunnel Rat Ears to Mountaineer Kadrell in Thelsamar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[417] = { title = "A Pilot's Revenge", description = "Hildelve wrote in his journal that he was attacked by Mangeclaw, a \"huge Ice Claw Bear.\"  He drove off the beast, but not before it mauled him savagely.\n\nJudging from the state of Hildelve's body, Mangeclaw must have later returned and killed him.\n\nHowever, Hildelve wrote in his journal his one, final wish:\n\nRevenge against Mangeclaw.", objectives = "Kill Mangeclaw.\n\nBring his Mangy Claw and Hildelve's Journal to Pilot Hammerfoot.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[418] = { title = "Thelsamar Blood Sausages", description = "There's never a shortage of empty bellies here in Thelsamar, kids running in and out, workers from the excavation coming in after  a hard day's work. We're famous for our blood sausages, I don't suppose you've ever tried them?\n\nNo? Well, around here you've got to work for your meals, and don't think just because you're a fancy $c, you'll be any exception.\n\nI'll need bear meat, boar intestines for the casings, and spider ichor for spice. You get me some of those, and leave the cooking to Vidra!", objectives = "Bring 3 pieces of Bear Meat, 3 Boar Intestines, and 3 Spider Ichor to Vidra Hearthstove in Thelsamar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[419] = { title = "The Lost Pilot", description = "My friend and fellow Siege Engine pilot, Mori Hildelve, is lost in the hills.  We were looking for a rare ore that's needed for a high-grade blastpowder, and during our search he drove his engine up a steep hill and busted it!\n\nStill convinced that ore was in these mountains, Hildelve charged me to guard our engines while he continued on foot, searching.\n\nIt's been days, and I've heard some beastly growls in the hills at night.  Mori's tough as nails, but I'm worried.\n\nPlease, $N.  Find him.", objectives = "Find Pilot Hildelve.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[420] = { title = "Senir's Observations", description = "The troggs in the tunnel are extremely hostile, and haven't shown any hesitation in attacking travelers through the tunnel. You seem tough enough, though, so you should probably be safe.\n\nDirections? If you're going to speak with Senir, you'll find him in Kharanos.\n\nMake your way through the tunnel, and after you come out on the other side, just keep following the road, it'll run right into Kharanos.", objectives = "Deliver Grelin's report to Senir Whitebeard in Kharanos.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[421] = { title = "Prove Your Worth", description = "Lady Sylvanas has charged Varimathras with the conquering of the human and dwarven lands to the south.\n\nBut that fool, Arugal -- charlatan of Dalaran and now cursed beast of Shadowfang Keep -- let his reckless magic wreak havoc with the strategic stronghold of Silverpine Forest.\n\nI need someone skilled in the ways of combat to help clean up Arugal's mess.  Prove yourself to me by killing 5 Moonrage Whitescalps.  The wretched beasts can often be found just off the road, down the hill below.", objectives = "Dalar Dawnweaver at the Sepulcher wants you to kill 5 Moonrage Whitescalps.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[422] = { title = "Arugal's Folly", description = "How Arugal gained acceptance within the Kirin Tor is beyond me.  His spell-casting knowledge seemed as transparent as a blown glass bauble.\n\nWhat's important now is learning exactly what magic Arugal used so that I can turn it against him and secure Silverpine Forest for the Dark Lady.\n\nArugal first stayed at the wheat farm just north of the bridge.  One of the Deathstalkers reported seeing some spellbooks but could not secure them.  Retrieve for me the spell labeled Remedy of Arugal from those books.", objectives = "Retrieve the Remedy of Arugal for Dalar Dawnweaver at the Sepulcher.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[423] = { title = "Arugal's Folly", description = "After examining Arugal's work my worst suspicions were confirmed.  The old hack was not qualified to clean chamber pots in Dalaran let alone represent the Kirin Tor in its most dire hour.  Fools!\n\nArugal used enchanted items to reinforce his weak magic.  I need to examine these items first hand.  Travel forth and slay Moonrage Gluttons and Moonrage Darksouls until you have collected enough of their enchanted shackles for my research.  The foul creatures have been seen to the north and east.", objectives = "Bring 6 Glutton Shackles and 3 Darksoul Shackles to Dalar Dawnweaver at the Sepulcher.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[424] = { title = "Arugal's Folly", description = "It will indeed take me longer than I had thought to uncover the dark secrets behind the enchantments Arugal was using.\n\nBut in the meantime I need you to take care of a slight problem our Darkstalkers have discovered.  It seems that Arugal let his magic spread to the Deep Elem Mine in the hills to the southeast.\n\nThe mine would prove to be quite a resource for Varimathras's advance.\n\nI want you to behead the tainted foreman of the mine, Grimson the Pale.  With his death, the mine shall be ours.", objectives = "Kill Grimson the Pale and bring his head to Dalar Dawnweaver at the Sepulcher.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[425] = { title = "Ivar the Foul", description = "My brother Quinn and I were tasked to recon Silverpine Forest and report to High Executor Hadrec.  But we didn't get far -- when moving through this farm we were attacked by the ghoul Ivar the Foul.\n\nWe escaped from Ivar, but he seriously mauled Quinn.  He's healing from the potion you gave him, but Ivar may return before Quinn recovers.\n\nKill Ivar so Quinn will have time to heal.  Ivar is usually in the barn yonder, waiting for my guard to drop.", objectives = "Kill Ivar the Foul, and bring Ivar's Head to Rane Yorick at the Ivar Patch.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[426] = { title = "The Mills Overrun", description = "The Scourge are trying to form a base at the Agamand Mills.  If they do, then they can stage further attacks within Tirisfal.\n\nThe orders have been given.  The Scourge in the Mills must be destroyed.\n\nGo to the Mills.  Collect Notched Ribs from Rattlecage and Cracked Skull Soldiers, and Blackened Skulls from Darkeye Bonecasters.\n\nTo get to the Mills, follow the road west.  After crossing the bridge, take the next fork north then keep going north.  When you see windmills, the battle will begin.", objectives = "Gather 5 Notched Ribs and 3 Blackened Skulls, then return to Deathguard Dillinger in Brill.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[427] = { title = "At War With The Scarlet Crusade", description = "The documents Executor Arren provided are just the break we needed in our battle with the wretched Scarlet Crusade.  We now know their exact locations throughout Tirisfal Glades.\n\nBut the Deathguard has larger concerns.  The Lich King's army grows in number each night.  We need someone with \"initiative\" like yourself to drive the Scarlet Crusade to the grave.\n\nProve to me you are capable of serving The Dark Lady by travelling west to the tower past the Solliden Farmstead and slay 10 Scarlet Warriors.", objectives = "Executor Zygand of Brill wants you to kill 10 Scarlet Warriors.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[428] = { title = "Lost Deathstalkers", description = "A couple weeks ago two of our Deathstalkers, Rane and Quinn Yorick, were sent on a reconnaissance mission through northern Silverpine.  We have not heard from them.\n\nThey may have become victim to the Scourge, though if that is true then I want it confirmed.  Find these Deathstalkers.\n\nTheir first objective was to scout the farms in northern Silverpine.  You should begin your search there.", objectives = "Find the Deathstalkers Quinn and Rane Yorick.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[429] = { title = "Wild Hearts", description = "My brother Quinn was badly hurt by the ghoul, Ivar the Foul, and I don't know if he will heal properly without magical aid.  Although I am not an apothecary, I do know that our apothecaries can make healing potions from the discolored hearts of worgs.\n\nGather such hearts and take them to Apothecary Renferrel at the Sepulcher to the south.  Then return here with the potion.\n\nYou can find plenty of worgs between here and Malden's Orchard to the east.", objectives = "Gather 6 discolored worg hearts and bring them to Apothecary Renferrel at the Sepulcher.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[430] = { title = "Return to Quinn", description = "Here is the potion to aid in Quinn Yorick's recovery.\n\nNow if you will excuse me, I have very important work to continue...", objectives = "Bring Quinn's potion to Quinn Yorick at the Ivar Patch, north of the Sepulcher.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[431] = { title = "Candles of Beckoning", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[432] = { title = "Those Blasted Troggs!", description = "Those Light-blasted troggs, turning my work site into a wreck! Look at that, there goes another barrel of powder!\n\nOhhh, I wish I could go down there and wring every one of their scrawny little necks! I want to kill them all!\n\nThis can't be good for my health, all this stress and anger... What have they left me with? Nothing!\n\nI'd kill them myself, but my aim's no good anymore! You go into the quarry and kill some of the filthy buggers! I'll pay you! Just hurt them, kill them!", objectives = "Kill 6 Rockjaw Skullthumpers for Foreman Stonebrow at the Gol'Bolar quarry.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[433] = { title = "The Public Servant", description = "As a member of the Senate and the Explorers' League, I've taken it upon myself to take care of this part of the trogg infestation that has gripped our lands.\n\nThey've certainly made a mess of Gol'Bolar quarry, and for no reason. As we dug deep into the earth, they poured out, destroying our equipment and driving the miners out. There's not much for us to do but to exterminate the lot of them, rebuild, then get back to work.\n\nIf you help me with the troggs, I'll gladly recompense you for your time.", objectives = "Kill 10 Rockjaw Bonesnappers for Senator Mehr Stonehallow at the Gol'Bolar quarry.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[434] = { title = "The Attack!", description = "After I put on Spybot's disguise, he'll head in to talk to Lescovar. The guards should let him pass no problem.\n\nWhile you were getting materials for me, I took care of informing Marzon that it was time for him and Lescovar to meet again. I even dropped some false information.\n\nLescovar will dismiss his guards and wait for Marzon out here in the garden. After you catch wind of talk about the Defias, make your move. You need to kill them both before the guards return! When you're done, speak to Trias.", objectives = "Remain in the garden until Lord Gregor Lescovar and Marzon the Silent Blade have had their conversation. Afterwards, kill them both before returning to Elling Trias in Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[435] = { title = "Escorting Erland", description = "The wolves outside won't leave, and they eye me evilly every time I step foot out that door.  They must be incredibly hungry to think I'm worth eating.\n\nI have to report to my teammate, the Deathstalker Rane Yorick.  And to get to Rane, I'll need help against those wolves.\n\nPlease escort me!  And there are a lot of wolves out there, so we'll have a better chance if you have friends who can help...", objectives = "Escort Erland through the wolves, to Rane Yorick.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[436] = { title = "Ironband's Excavation", description = "Prospector Ironband is heading an excavation of ancient ruins east of the lake.  His progress has been slow lately, especially considering all the supplies we've sent him.\n\nIronband's a stout, honest dwarf who values results, which has me worried that forces are at work against him.\n\nGo to Ironband's Excavation and speak with Magmar Fellhew.  He manages the details of the site and will know why there's a slowdown.\n\nTo get to the excavation site, go around the southern tip of the lake, then head east.", objectives = "Speak with Explorer Fellhew.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[437] = { title = "The Dead Fields", description = "Our initial scouting reports of Silverpine show the rot hides have a base at an old farm to the north, the Dead Fields.  We have sent small assaults against them, but each time they are reinforced by the banshee Nightlash, who uses her magic to rout our forces.\n\nWe want Nightlash destroyed.\n\nGo to the Dead Fields and assault the rot hides.  If you don't see Nightlash then kill the rot hides until she appears, then defeat her.\n\nHer essence will turn to dust.  Bring me that dust as proof.", objectives = "Kill rot hide gnolls at the Dead Fields.\n\nWhen Nightlash appears, kill her.\n\nBring the Essence of Nightlash to High Executor Hadrec at the Sepulcher.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[438] = { title = "The Decrepit Ferry", description = "$N, we've discovered a new hive for the Scourge: the Decrepit Ferry.  The ferry lies east of the Sepulcher, and is heavily patrolled by rot hides and other undead.\n\nThere must be a reason for the Scourge's occupation of the area.  Go to the Decrepit Ferry and find out why the Scourge are there.", objectives = "Go to the Decrepit Ferry.\n\nSearch for the reason the Scourge are there.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[439] = { title = "Rot Hide Clues", description = "Among the corpses a hand protrudes, unwrapped.  It is the hand of a woman, pockmarked from the plague but relatively fresh.  \n\nOn the hand is a ring.  Removing the ring and inspecting it reveals an engraving:\n\n\"For Deliah\"", objectives = "Bring Deliah's Ring to High Executor Hadrec at the Sepulcher.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[440] = { title = "The Engraved Ring", description = "If you want to find the husband or beloved who gave Deliah her ring... then speak with Magistrate Sevren in Brill.  He should have records of recent deaths and, with luck, can discover who Deliah is.\n\nBut I wouldn't hope.  Whoever gave her the ring is probably dead.  Or if he's undead he probably no longer cares about Deliah.", objectives = "Bring Deliah's Ring to Magistrate Sevren in Brill.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[441] = { title = "Raleigh and the Undercity", description = "Deliah had a husband, Raleigh, who now dwells in the Undercity.  If the Deliah who lived in Brill is the one who owned this ring, then Raleigh will know.\n\nRaleigh is in the Trade Quarter of the Undercity.", objectives = "Bring Deliah's Ring to Raleigh.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[442] = { title = "Assault on Fenris Isle", description = "Now is the time to assault the Scourge's place of strength in Silverpine: Fenris Isle.\n\nYou must again go to the Isle and destroy Thule Ravenclaw.  I want his head!\n\nThis mission is as dangerous as it is vital, $N.  You must not fail.", objectives = "Bring Thule's Head to High Executor Hadrec at the Sepulcher.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[443] = { title = "Rot Hide Ichor", description = "Before we launch an assault on Fenris Isle, we must determine who is behind the rot hide gnolls.  Our apothecaries believe their origin lies within the strange fluid that flows through their bodies.\n\nGo to Fenris Isle, east of the Decrepit Ferry, and collect rot hide ichor from the gnolls you find there.  Bring it to Apothecary Renferrel, stationed outside the Sepulcher.", objectives = "Bring 8 bottles of rot hide ichor to Apothecary Renferrel at the Sepulcher.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[444] = { title = "Rot Hide Origins", description = "I have reduced the ichor you brought me and separated it into its base components.  My findings are not conclusive, but I have determined that warlock and necromantic magics were used in the ichor's creation.\n\nWhile I continue to study the ichor, I want you to take a sample to Bethor Iceshard in the Undercity.  Bethor is not an apothecary, but his knowledge of magic may help to unravel the mystery of the rot hides.\n\nGo.  You will find Bethor in the Magic Quarter of the Undercity.", objectives = "Bring the Sample Ichor to Bethor Iceshard in the Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[445] = { title = "Delivery to Silverpine Forest", description = "Time is a luxury that is not afforded to those of us under the employ of Lady Sylvanas.  Surely you know this by now.\n\nAs a member of the Royal Apothecary Society it is my duty to share my knowledge with my colleagues so that our collective efforts might one day provide The Dark Lady with the New Plague she so badly desires.\n\nTake these findings to Apothecary Renferrel who is stationed at The Sepulcher in Silverpine Forest.  Follow the roads to the south from Brill.  From the Undercity go southwest.", objectives = "Take Apothecary Johaan's findings to Apothecary Renferrel in Silverpine Forest.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[446] = { title = "Thule Ravenclaw", description = "This Ichor was crafted by an old colleague of mine: Thule Ravenclaw.  He was a young, promising mage before the great war, but when the Lich King rose to power, he betrayed his brethren and allied with the Scourge.\n\nI did not realize he still lives, nor that he leads the Rot Hides in their forays against us!\n\nI know many of his spells, and can help concoct a potion to counter them.  Take this scroll back to Apothecary Renferrel.  It has the incantations needed for the potion.", objectives = "Bring Bethor's Scroll to Apothecary Renferrel at the Silverpine Sepulcher.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[447] = { title = "A Recipe For Death", description = "Arthas's numbers are overwhelming. But with a New Plague we could eradicate both the Scourge Army and the Human infestation once and for all.\n\nMy studies have proven that spider blood combined with a toxin derived from a grizzled bear heart results in a deadly elixir. Collect samples from the spiders in the Skittering Dark to the northwest and from the bears wandering throughout Silverpine Forest. Deliver the reagents to Master Apothecary Faranell of the Royal Apothecary Society in the Undercity.", objectives = "Collect 6 Grizzled Bear Hearts and 6 samples of Skittering Blood and deliver them to Master Apothecary Faranell in the Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[448] = { title = "Report to Hadrec", description = "Before you launch an assault on Fenris Isle, report to High Executor Hadrec.  He may have additional information or equipment you'll need.", objectives = "Report to High Executor Hadrec at the Sepulcher.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[449] = { title = "The Deathstalkers' Report", description = "Although Quinn's wounds are mending, I want to get our report to High Executor Hadrec as quickly as possible.  It has information that is vital to the Forsaken's occupation of Silverpine.", objectives = "Bring the Deathstalker Report to High Executor Hadrec at the Sepulcher.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[450] = { title = "A Recipe For Death", description = "You can be of further service to the Royal Apothecary Society, $N.\n\nWhen Arugal cast his wretched magic on the forest, he cursed one of our most promising members, Apothecary Berard.  Now a mindless servant of Arugal, Berard is useless to us.  But his findings might prove to be of worth.  He was studying an ancient plague that killed off all the aquatic life in Lake Lordamere ages ago.\n\nRetrieve Berard's Journal from his study in the Pyrewood Village Inn and take it to Apothecary Renferrel.", objectives = "Retrieve Apothecary Berard's journal from Pyrewood Village and take it to Apothecary Renferrel at the Sepulcher.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[451] = { title = "A Recipe For Death", description = "According to Berard's Journal the moss from Lake Skulkers and Creepers might prove useful for our quest to brew a new plague.  Those beasts dwell on the islands in Lake Lordamere to the east.\n\nHe also mentions a very rare Hardened Tumor that he discovered on a Vile Fin murloc.  Apparently the tumor is so rare Berard was only able to obtain one.\n\nCollect samples of the moss as well as the rare hardened tumor and take them to Master Apothecary Faranell in the Undercity.", objectives = "Bring 6 samples of Lake Creeper Moss, 6 samples of Lake Skulker Moss and a Hardened Tumor to Master Apothecary Faranell in the Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[452] = { title = "Pyrewood Ambush", description = "You got here just in the nick of time, $N!\n\nThe Pyrewood Council will be returning any moment.  Arugal has other matters to tend to in the keep.  He uses the Council as mere puppets to keep the mindless minions of Pyrewood under his control.  But I believe that without the guidance of the Pyrewood Council, the sons of Arugal will turn against their master.\n\nI cannot handle them all by myself.  I need you to help me.  Together we can lay waste to the Council for Lady Sylvanas.", objectives = "Help Deathstalker Faerleia kill the Pyrewood Council.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[453] = { title = "Finding the Shadowy Figure", description = "Good luck, $N.  I hope you find the chap, and I hope you find him alive.\n\nIf he's left the safety of Darkshire then he could be prey to the beasts of the wilds.", objectives = "Find the Shadowy Figure.  Your clues:\n\nHe is not native to Darkshire.\n\nHe is a nervous, jittery person.\n\nHe left Darkshire and headed west.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[454] = { title = "After the Ambush", description = "We'd been hauling the barrels of powder back and forth in trips before this... business. Now we have to split up the work, Miran's taking the barrels and I'm watching over the other ones.\n\nI don't feel safe letting Miran haul the rest of the shipment by himself. When he's ready to go, maybe you could escort him on his next trip?", objectives = "Speak with Miran.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[455] = { title = "The Algaz Gauntlet", description = "Orcs of the Dragonmaw clan have a haven in the Wetlands.  And now they have expanded into Dun Algaz!  We can't let them keep their foothold here or Loch Modan will be cut off from Menethil Harbor, our port and stronghold in the Wetlands.\n\nBreak through Dun Algaz to the Wetlands beyond, and kill some orcs for good measure!  Report to Valstag Ironjaw in Menethil Harbor.\n\nMenethil is through Dun Algaz, then north along the road, then west at the fork.\n\nWe're counting on you, $N.  Do not fail.", objectives = "Traverse Dun Algaz.\n\nKill 8 Dragonmaw Scouts and 6 Dragonmaw Grunts.\n\nReport to Valstag Ironjaw in Menethil Harbor.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[456] = { title = "The Balance of Nature", description = "Greetings, $N.  I am Conservator Ilthalaine.  My purpose in Shadowglen is to ensure that the balance of nature is maintained.\n\nThe spring rains were particularly heavy this year, causing some of the forest's beasts to flourish while others suffered.\n\nUnfortunately, the nightsaber and thistle boar populations grew too large.  Shadowglen can only produce so much food for the beasts.  Journey forth, young $c, and thin the boar and saber populations so that nature's harmony will be preserved.", objectives = "Kill 7 Young Nightsabers and 4 Young Thistle Boars and return to Conservator Ilthalaine.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[457] = { title = "The Balance of Nature", description = "Thinning the younger population of creatures here in Shadowglen was a good start, $N, but there is still work to be done.\n\nThe resources of the forest will be depleted too quickly if the problem is not addressed.  Killing nature's beasts is a necessary evil for the good of all who share the land.  Venture into the forest and slay mangy nightsabers and thistle boars in the name of balance.", objectives = "Conservator Ilthalaine needs you to kill 7 Mangy Nightsabers and 7 Thistle Boars.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[458] = { title = "The Woodland Protector", description = "Thank goodness you are here, $c. Strange news has traveled to me through the whisperings of the forest spirits.\n\nThe mysterious woodland protector, Tarindrella, has returned to Shadowglen. The dryad's presence has not been felt in the forests of Kalimdor in years. Something is surely amiss if she has journeyed back to this land.\n\nSeek out Tarindrella and see what business she tends to in our grove. One of the Sentinels reported seeing her to the southwest of Aldrassil.", objectives = "Seek out the dryad known as Tarindrella.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[459] = { title = "The Woodland Protector", description = "Something evil is brewing in the forests of Teldrassil.  Look long the hills to where the peaceful furbolgs used to dwell.  They have deserted their homes and are amassing under the name of the Gnarlpine tribe.\n\nOnly the corruption of wicked Fel Moss could cause such a transformation.  The grells and grellkin have infested the area and are threatening the residents of Shadowglen.  \n\nEngage these grells and grellkin, $N, and see if they are indeed caught under the enchantment of the wicked Fel Moss.", objectives = "Collect 8 Fel Moss and bring them to Tarindrella.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[460] = { title = "Resting in Pieces", description = "You don't look like a rot hide.  Good.  I had lost hope...\n\nMy name is Alaric, and I was once Thule's head servant and bodyguard.  He used his magic to \"protect\" me from the Plague of Undeath, but instead his spell gave me an unlife from which I cannot escape.  And after creating the cursed rot hide gnolls, Thule beheaded me... and gave my head to the gnolls as a plaything!\n\nPlease, take me to my body.  I believe the gnolls buried it here in Fenris Keep, near the stable, in an unmarked grave.", objectives = "Bring Alaric's Head to his grave.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[461] = { title = "The Hidden Niche", description = "I know of a hidden niche within the keep that holds an item dear to Thule, and his old colleagues.  It also holds something you might find useful.  Take me there!\n\nThe alcove is in the southwestern tower of the keep, behind a dusty shelf.\n\nTake my body, but leave my boots.  They never fit me anyway...", objectives = "Take Alaric to the hidden alcove.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[463] = { title = "The Greenwarden", description = "You've heard of the Greenwarden?  You're not looking for him, are you?  Well I say you're crazy if you are, but who am I to keep a fool from $ghis:her; death?\n\nIf you are seeking that beast, then I hear he is in the marsh, east of the road where it forks to Dun Modr.  He's lurking there among the crocs...and worse!\n\nAnd leave your money here.  You won't need it where you're going...and you don't want to chip ol' Greenie's tooth on your gold when he bites you in half, do you?", objectives = "Find the Greenwarden.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[464] = { title = "War Banners", description = "The Dragonmaw orc clan was all but destroyed by the end of the Second War, after they lost control of their red dragon pets.  The dragons were not very happy with their old masters, and fiercely hunted the Dragonmaws.  What few remained fled from Grim Batol and into the Mountains east of Whelgar's Excavation.\n\nNow they've gained strength, and have an encampment northeast of Menethil.\n\nWe want you to attack that encampment.  Gather and bring me their war banners as proof.", objectives = "Bring 8 Dragonmaw War Banners to Captain Stoutfist.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[465] = { title = "Nek'rosh's Gambit", description = "While you were fighting the Dragonmaws, we discovered more of their plans.\n\nNek'rosh has built catapults and aims to lay siege to Menethil!  And with the fighting in Dun Algaz, we're effectively blocked from reinforcements!\n\nYou need to take out those catapults.  They're in the Dragonmaw encampment.\n\nHere, take this tinder.  Fight your way to the catapults and light them with the tinder.\n\nAnd after you've done that, find and kill Nek'rosh.  We need to cut this Dragonmaw beast down...at its neck.", objectives = "Destroy the Dragonmaw catapults.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[466] = { title = "Search for Incendicite", description = "I heard that a rare ore, incendicite, was found in the Wetlands, in a cave northwest of Algaz Gate.  Incendicite is volatile stuff and hard to use without blowing yourself up, but I'm sure if it's smelted the right way it could make cannon shells that pack a mighty punch!\n\nGet me incendicite ore and I'll find someone brave enough to experiment with it.\n\nOh, and to extract that ore from a vein you'll need skill in mining.  If you don't have it, then ... bring a friend who does to that cave!", objectives = "Bring 6 loads of Incendicite Ore to Pilot Stonegear in Dun Morogh.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[467] = { title = "Stonegear's Search", description = "Pilot Stonegear loves his siege engine, as every pilot should!  And he's always eager to find new ways to improve his tank's firepower!\n\nHe heard rumors of a rare ore and is looking for someone to hunt it down for him.  If your boots are starting to itch, then find Stonegear at Steelgrill's Depot in Dun Morogh and see what he wants.", objectives = "Speak with Pilot Stonegear.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[468] = { title = "Report to Mountaineer Rockgar", description = "Mountaineer Rockgar is looking for volunteers for a mission through Dun Algaz and into the Wetlands.  \n\nIf you want to get your boots wet in that soggy county to the north, then speak with Rockgar at Dun Algaz.  Dun Algaz is north up the road, beyond the guard tower.", objectives = "Speak with Mountaineer Rockgar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[469] = { title = "Daily Delivery", description = "Greetings, traveler!\n\nDon't suppose you might be heading in the direction of Menethil, would you? If you're not, I'd suggest you stop there, it's a good place to purchase goods and even have a pint and relax.\n\nNow, if it just so happens that you're heading in that direction, I don't suppose you'd mind taking this bundle of crocolisk skins to James Halloran, the tanner?\n\nI'd do it myself, but my wife's been in quite a mood lately, and I'd like to put off facing her as long as possible.", objectives = "Deliver the Bundle of Crocolisk Skins to James Halloran, the tanner, in Menethil Harbor.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[470] = { title = "Digging Through the Ooze", description = "On my weekly visit to Ironbeard's Tomb I was attacked by dreadful, dripping oozes! Naturally, I panicked.\n\nI threw my bag at one, but it didn't do anything! The ooze just sucked it right up... Luckily, it did give me enough time to get away.\n\nThe bad news is that I really need to get the contents of my bag!\n\nI don't know which ooze I threw my bag at; they all looked the same! Ironbeard's Tomb is northeast of here, near Dun Modr. Thank you so much!", objectives = "One of the oozes at Ironbeard's Tomb has Sida's bag, retrieve it and bring it back to her in Menethil Harbor.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[471] = { title = "Apprentice's Duties", description = "I sent my apprentice out into the marshes to skin some of our famous giant Wetlands crocolisks. When he didn't return, I went out to look for him... Let's just say it wasn't a pretty sight.\n\nMidwife says he might pull through, but in the meantime I still need my skins!\n\n...If you'd like to kill a few more of the brutes, I wouldn't be opposed, after what they did. You'll find the crocs north up the coast, beyond the murloc hovels.", objectives = "Collect 6 Giant Crocolisk Skins and bring them to James Halloran in Menethil Harbor.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[472] = { title = "Fall of Dun Modr", description = "Dun Modr has fallen to the Dark Iron Dwarves!\n\nMy wounds are grave, $c.  Most of the regiment was killed!  The Dark Iron thugs attacked us before we could regroup from the Thandol Span ambush.\n\nOur leader, Longbraid, sounded the retreat horn.  As we left the town I was hit by a stray axe in the back.  All went black.\n\nI awoke here in Menethil but I fear for my fellow soldiers.  Hope still burns within me.  Perhaps Longbraid is still alive!  See if you can find him near Dun Modr, $r!", objectives = "Search for Longbraid near the town of Dun Modr.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[473] = { title = "Report to Captain Stoutfist", description = "$N.  The Dragonmaw orc clan is showing its strength in more than just Algaz.  Captain Stoutfist has asked to speak with those willing to offer aid against these orcs.  He is inside the keep, in the war room.", objectives = "Speak with Captain Stoutfist.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[474] = { title = "Defeat Nek'rosh", description = "Now that the catapults have been burned, find and kill Chieftain Nek'rosh.", objectives = "Kill Chieftain Nek'rosh\n\nBring Nek'rosh's Head to Captain Stoutfist.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[475] = { title = "A Troubling Breeze", description = "A troubling breeze blows through the forest.\n\nGaerolas Talvethren serves as Great Warden to the hibernating Druids of the Talon in the Ban'ethil Barrow Den.  His duty as the chosen protector of the Sleeping is to ensure their safety so that their pact with Ysera remains fulfilled.\n\nBut word from Gaerolas is now delayed and I grow nervous.  Travel east to Starbreeze Village and bring back a report from Gaerolas so that I can put my worries to rest, knowing my dreaming brethren slumber safely.", objectives = "Seek out Gaerolas Talvethren in Starbreeze Village.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[476] = { title = "Gnarlpine Corruption", description = "The Gnarlpine tribe has been corrupted!\n\nThe once peaceful furbolgs have turned against the protectors of the forest.  They ambushed me as I left for the Ban'ethil Barrow Den and proceeded to pillage Starbreeze Village.  Ursal the Mauler, their chieftain, is using the evil powers of the Fel Moss to drive them mad.\n\nI am too wounded to return to Athridas to bring him this grave news.  The task is left to you, young $c.  We can only hope that the deranged Gnarlpines have not made it to Ban'ethil yet!", objectives = "Return to Athridas Bearmantle in Dolanaar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[477] = { title = "Border Crossings", description = "As you may know, the town of Ambermill remains a source of human opposition, mainly through the support they receive from the wizards of Dalaran.\n\nI don't know what their plan is, but for them to show interest in a backwater village like Ambermill indicates that it must have some greater importance.\n\nThey've been shipping crates by the wagon from Hillsbrad. Many of those supplies end up at a small camp north of Pyrewood Village. Retrieve the contents of a crate and return them to me.", objectives = "Retrieve the contents of one of the Dalaran wizards' crates. You will find Pyrewood Village to the south.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[478] = { title = "Maps and Runes", description = "<You quickly remove the pendant from the crate and replace the lid.>", objectives = "Bring the strange pendant to Shadow Priest Allister at the Sepulcher.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[479] = { title = "Ambermill Investigations", description = "Dalar is attempting to locate the source of the wizards' spellcasting. For now, we'll have to slow their progress in any way we can...\n\nThe conjurers, mages and protectors are no doubt carrying the pendants. Remove and retrieve them.\n\nTake the main road south and the eastern fork into Ambermill.", objectives = "Obtain 8 Dalaran Pendants for Shadow Priest Allister at the Sepulcher.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[480] = { title = "The Weaver", description = "An archmage of great power is overseeing the reactivation of the ley energy node. With the progress they have made, our only hope of stopping them is by killing him. It will be difficult, he is no doubt protected by many other mages and warders.\n\nYou must go, and you must dispatch him quickly. When he is dead, retrieve his staff for me. Go now.", objectives = "Kill the Dalaran archmage, then retrieve his staff for Shadow Priest Allister at the Sepulcher.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[481] = { title = "Dalar's Analysis", description = "Take the pendant to Dalar Dawnweaver, perhaps he can shed some light on the wizards' plans.", objectives = "Take the rune-inscribed pendant to Dalar Dawnweaver at the Sepulcher.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[482] = { title = "Dalaran's Intentions", description = "Of course! How could I have forgotten?\n\nAmbermill was one of the sites earmarked by the Kirin Tor, noted because it houses a dormant ley energy node. The wizards must be planning to reactivate the node and use its energies for some greater purpose.\n\nWe cannot allow this to happen...\n\nIt will take a great amount of power to activate the area's ley energies, we can stall them by taking the pendants away from the wizards.\n\nRelay this information to Allister, he will decide a course of action.", objectives = "Speak with Shadow Priest Allister at the Sepulcher.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[483] = { title = "The Relics of Wakening", description = "Gnarlpine invaders were seen ravaging the Ban'ethil Barrow Den to the west.\n\nThe slumbering druids will be trapped in the Emerald Dream for eternity, unaware of their fate, unless we help. The delicate hibernation ritual cannot be broken without the Relics of Wakening.\n\nJourney to the Den and retrieve the Raven Claw Talisman, Black Feather Quill, Sapphire of Sky, and Rune of Nesting. The druids store them in sacred chests.  Return them to me and I will prepare the awakening ritual.", objectives = "Retrieve the Relics of Wakening and bring them to Athridas Bearmantle in Dolanaar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[484] = { title = "Young Crocolisk Skins", description = "I'm James Halloran, the tanner. My cured crocolisk skins are sought after all over, shipments leaving by boat to ports around the world.\n\nMet Einar? He's one of the hunters that brings crocolisk skins in for me.\n\nI'm a bit short on the softer skins that come off crocolisk young.\n\nBeing that I'm running low, I'll pay you top coin for a stack of the skins. You can find the young crocs in the marshes right outside of town.", objectives = "Obtain 4 Young Crocolisk Skins for James Halloran in Menethil Harbor.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[485] = { title = "Find OOX-09/HL!", description = "You have uncovered some sort of strange, egg-shaped device made from metal.  Fiddling with one of its knobs springs the egg to life, as it opens up into some sort of gnomish robotic contraption!  A voice from inside the robotic egg crackles to life.\n\n\"My name's Oglethorpe Obnoticus, and my homing robot has crashed!  I will reward you for its recovery; please take this beacon to the robot!\"\n\n\"I now have computed the coordinates of the robot for you; it crashed at the head of the river near Skulk Rock!\"", objectives = "Take the distress beacon to Oglethorpe's homing robot at the head of the river in the Hinterlands, near Skulk Rock.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[486] = { title = "Ursal the Mauler", description = "Now the time has come to save the Druids of the Talon. If we fail now, $N, they will be forever lost in sleep.\n\nI shall prepare the Relics of Wakening and perform the ritual. For my work to take effect, the cursed beast responsible for this horrible situation must be slain.  Only then will the ritual be complete.\n\nIt was Ursal the Mauler who meddled with our brethren's calling and it is Ursal the Mauler who must now pay so they can be freed.  Travel to Gnarlpine Hold in the southwest and slay him.", objectives = "Kill Ursal the Mauler and return to Athridas Bearmantle in Dolanaar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[487] = { title = "The Road to Darnassus", description = "The road to Darnassus must be kept safe.  Travelers heading from Dolanaar to Darnassus have been reporting ruthless attacks by corrupted furbolgs from the Gnarlpine tribe.\n\nImportant news and commerce travels to and from Darnassus by way of this road daily.  We cannot afford to have a rogue band of heathens terrorizing people.\n\nTake up arms in the name of the sacred forest, $c.  Their den lies somewhere below this vantage point.  Slay 6 of these Gnarlpine ambushers and report back to me.", objectives = "Slay 6 Gnarlpine Ambushers and return to Sentinel Amara Nightwalker outside of Dolanaar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[488] = { title = "Zenn's Bidding", description = "Eager for work, I see.  Lucky for you a day never goes by that I don't wish I had a fledgling $c to perform my bidding.\n\nYou see, $N, I can make you very happy and provide you with things you never dreamed of having.  But in order for that to happen you must bring me certain items.\n\nMy business in the forest often requires certain. . .reagents.  Fetch for me 3 Nightsaber Fangs, 3 Strigid Owl Feathers and 3 swatches of Webwood Spider Silk.\n\nLet's keep this our little secret, $r.", objectives = "Bring Zenn Foulhoof outside of Dolanaar 3 Nightsaber Fangs, 3 Strigid Owl Feathers and 3 swatches of Webwood Spider Silk.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[489] = { title = "Seek Redemption!", description = "The Council of the Forest has news that you aided Zenn Foulhoof. The satyr is an enemy of the forest. As a $r, you should know better than to defile the forest by killing Nature's creatures.\n\nYou must redeem yourself in the eyes of the Council if you wish to remain a friend of Teldrassil.\n\nTeach Foulhoof a lesson and you shall be redeemed. Fel Cones are corrupted seeds that fall from the trees. They billow with green smoke.\n\nGive some to Foulhoof. He'll think you have brought him a harmless snack.", objectives = "Collect 3 Fel Cones and give them to Zenn Foulhoof outside of Dolanaar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[491] = { title = "Wand to Bethor", description = "Thule once told me that, long ago, he and two colleagues created a magic wand, woven together from the apprentice wands each mage possessed.  This wand was a symbol of their friendship, and although Thule came to despise it he could not part with it, nor could he let the others have it.  So he stole the wand, and hid it in Fenris Keep.\n\nHere.  Take the wand to Bethor Iceshard, one of Thule's friends from years past.  I'm sure he will want it.", objectives = "Take the Woven Wand to Bethor Iceshard in the Magic Quarter of the Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[492] = { title = "A New Plague", description = "According to the Deathguard, another one of those foolish Dwarven Mountaineers has just been captured.  The Deathguard likes to use the cellar of the Gallows End Tavern as a holding cell until prisoners can be \"properly\" dealt with.\n\nWhy don't you go see how the Captured Mountaineer enjoys this special drink I made for him?  It contains a subtle hint of what The Dark Lady has planned for the rest of Azeroth.", objectives = "Bring Johaan's Special Drink to the Captured Mountaineer.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[493] = { title = "Journey to Hillsbrad Foothills", description = "The Royal Apothecary Society is under extreme pressure from the Dark Lady to develop a New Plague.  We are working diligently and have made much progress.  It is our belief that the success will be achieved much faster if we share information amongst the Society.\n\nFor that reason I want you to deliver my latest findings to Apothecary Lydon in Tarren Mill, a small town nestled in the Hillsbrad Foothills.  The journey will be a long one.\n\nHead south and stick to the roads.  Follow the signs closely!", objectives = "Deliver Apothecary Renferrel's findings to Apothecary Lydon in the town of Tarren Mill in the Hillsbrad Foothills.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[494] = { title = "Time To Strike", description = "Be silent and pay attention, $c.\n\nI was sent to this position in order to survey the town of Hillsbrad.  My mission is one of reconnaissance.  It is imperative that you send word to High Executor Darthalia in Tarren Mill at once.  Let her know that I, Deathstalker Lesh, send the following message:\n\n\"The raven's cry from the west doth beckon.\"\n\nFollow the road to the east and pay close attention to the signs.  Now, hurry!  Off you go to Tarren Mill, and with urgency I might add!", objectives = "Travel to Tarren Mill to deliver Deathstalker Lesh's message to High Executor Darthalia.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[495] = { title = "The Crown of Will", description = "Mug'Thol and his ogre warband was sent to Alterac to retrieve the Crown of Will for Lady Sylvanas. Unfortunately, instead of returning it, the idiot decided to try it on... I suppose ogres can't resist anything bright and shiny.\n\nHis bumbling actions have become something of a problem, however. The Crown of Will enabled him to resist the possession placed upon him to serve Lady Sylvanas.\n\nThe Dark Lady wants an example made, travel to Tarren Mill in Hillsbrad and report to Melisara, my lieutenant.", objectives = "Report to Melisara at Tarren Mill in the Hillsbrad Foothills.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[496] = { title = "Elixir of Suffering", description = "Ah, another wretched day in Tarren Mill.  All of this clean air puts me in such a foul mood, $N.\n\nThe sooner we can plague the humans here, the better.  I've been conducting intense studies on possible killing agents to use in my concoctions but I haven't the time to collect them all.\n\nIf you want to make yourself of use, procure the following items for me:  10 Gray Bear Tongues and the very rare and hard to find, Creeper Ichor.  You'll find both bears and creepers just outside of Tarren Mill.", objectives = "Apothecary Lydon of Tarren Mill wants 10 Gray Bear Tongues and some Creeper Ichor.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[498] = { title = "The Rescue", description = "Me and some other warriors were sent by the Warchief to retrieve an object from Durnholde and to investigate this so-called Syndicate.\n\nWe went to Durnholde to take a look around, but we were taken by surprise by a large number of the humans. We fought bravely, but their sheer numbers were enough to defeat us. They took a few of us captive, but I was able to escape.\n\nDurnholde is just southeast of here, across the river. Drull and Tog'thar are being held there, you must go and rescue them.", objectives = "Krusk in Tarren Mill needs you to free Drull and Tog'thar from Durnholde Keep.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[499] = { title = "Elixir of Suffering", description = "It will take but a moment for me to mix these components into what I have deemed an Elixir of Suffering.\n\nThere we go!  Ah, nothing brightens a gloomy day in these miserable foothills like bringing a little suffering into the world.\n\nLet us see if our little potion has achieved its desired effect.\n\nGive my assistant Umpi a taste of what the Dark Lady has planned for both humans and Scourge alike.", objectives = "Give Umpi the Elixir of Suffering.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[500] = { title = "Crushridge Bounty", description = "Crushridge ogres have dug an ogre mound up in the Alterac Mountains near the ruined city of Alterac.  And my scouts tell me they've taken over those ruins as well.\n\nWe can't let them get cozy up there; if they think they're safe where they are, then their next step will be to move down into the foothills, which will put them right at our front door!\n\nGo north to the Alterac Mountains and hunt ogres.  Bring me the Dirty Knucklebones they carry and you will earn a nice bounty.", objectives = "Gather 9 Dirty Knucklebones from Crushridge ogres in the Alterac Mountains.  Bring them to Marshal Redpath in Southshore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[501] = { title = "Elixir of Pain", description = "Oh, $N. . .the flowers are blooming in Hillsbrad and the air is so fresh and brisk.  I can't help but to wallow in the misery of it all.  I look out my grimy window and long for the day when our New Plague brings this world the death it deserves.\n\nAs much as I would love to sit and brood all day, my duty to the Dark Lady calls.  Help me, would you?  My research leads me to believe I can make the most splendid death-brew with the blood of a Mountain Lion.  Bring some to me and we'll have a little fun.", objectives = "Bring 10 vials of Mountain Lion Blood to Apothecary Lydon in Tarren Mill.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[502] = { title = "Elixir of Pain", description = "Ah, nothing like the smell of fresh blood in the foothills!\n\nNow we'll mix in a touch of this and a little of that and let the real fun begin!  What I have created with this blood, I like to call an Elixir of Pain.  If my calculations are correct this concoction could be the start of something very beautiful for Lady Sylvanas.  But what we need is a test.\n\nTake this elixir out to the northern farm in Hillsbrad Fields to the southwest.  Let's see how Farmer Ray's little dog Stanley likes this \"treat.\"", objectives = "Feed the Elixir of Pain to Stanley.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[503] = { title = "Gol'dir", description = "From what I can tell of the documents you procured, Gol'dir is being held in a large Syndicate base to the north, most likely in the Alterac Mountains. He has been held captive far too long and must be freed.", objectives = "Free Gol'dir then return to Krusk in Tarren Mill.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[504] = { title = "Crushridge Warmongers", description = "Now that you've had a taste of the Crushridge ogres, I want you to really bloody their noses...\n\nGo into the Ruins of Alterac and seek out the Crushridge Warmongers.  I want you to cut down a good number of them - that's the only way those brutes will learn to keep their distance from Alliance territory.", objectives = "Slay 15 Crushridge Warmongers, then return to Marshal Redpath in Southshore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[505] = { title = "Syndicate Assassins", description = "I am the new magistrate of Southshore, recently assigned after the assassination of the previous magistrate.  The assassins were never found, but through our investigations we're almost certain they were hired by the Syndicate - a group of thieves led by villainous nobles of the now fallen kingdom of Alterac.\n\nThe Syndicate has a camp north of the Horde-occupied Tarren Mill, and our last clues led to that camp.  Slay the Syndicate members you find there.", objectives = "Kill 12 Syndicate Footpads and 8 Syndicate Thieves, then return to Magistrate Henry Maleb in Southshore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[506] = { title = "Blackmoore's Legacy", description = "A day or two ago, I was visited by the leader of this Syndicate. His name was Aliden Perenolde, and styled himself lord of this land. He confided in me his plans to take the orcs that stood against him as slaves, just as his father and his mentor, the despised Blackmoore, had planned.\n\nMore important was that he brought his mistress, a wisp of a girl named Elysa. Around her neck was the pendant the Warchief desires.\n\nNow go, I will make my own way, after I have settled my business here.", objectives = "Return the information gathered by Gol'dir to Krusk in Tarren Mill.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[507] = { title = "Lord Aliden Perenolde", description = "It is clear that Perenolde must be killed, his foulness removed from the world. His manor lies a ways to the north of here, on the shores of Lordamere Lake. Do your duty, $n, then retrieve the pendant that the Warchief desires, and return here.", objectives = "Kill Lord Aliden Perenolde and ask his mistress, Elysa, about Taretha's pendant.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[508] = { title = "Taretha's Gift", description = "The pendant? Of course you can have it... Take it! I want no memory of him... just please, please leave in peace...", objectives = "Return Taretha's pendant to Krusk in Tarren Mill.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[509] = { title = "Elixir of Agony", description = "Another day, another elixir to be made. If it were up to me, I'd just let the pathetic humans and Scourge fight it out.  They seem bent on killing each other as is.\n\nAlas, our Dark Lady wants to help speed up the process a tad so why not pass these morbid days by spreading a little death and disease across the land?\n\nHere's the plan, $N: you go out to Nethander Stead, south of Tarren Mill and east of the river and Southshore. Collect for me 6 Mudsnout Blossoms from the field for my next elixir.", objectives = "Bring 6 Mudsnout Blossoms to Apothecary Lydon in Tarren Mill.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[510] = { title = "Foreboding Plans", description = "Among these documents is a list of requested supplies.  These include mundane items (food, weapons, clothing) as well as more exotic gear (masks, oil, poison).\n\nBut what is most notable is the urgency of the request - these supplies were needed soon in order to undertake what is described in the document as an \"important mission against Southshore.\"", objectives = "Bring the Foreboding Plans to Magistrate Maleb in Southshore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[511] = { title = "Encrypted Letter", description = "One of the letters on this table is encrypted and inscrutable.", objectives = "Bring the Encrypted Letter to Loremaster Dibbs in Southshore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[512] = { title = "Noble Deaths", description = "I fear the leadership behind the Syndicate is bent on Southshore's ruin.  We must strike hard at these leaders before their plans are realized.\n\nEnter the ruins of Strahnbrad, in the Alterac Mountains to the north.  We think the Syndicate is using the area as a headquarters.\n\nWe know this gang of cutthroats is run by former Alterac nobles.  They may be hiding as normal Syndicate agents, but you'll know you've killed a noble by the signet ring he wears.\n\nBring me those signet rings.", objectives = "Bring 7 Alterac Signet Rings to Magistrate Maleb in Southshore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[513] = { title = "Elixir of Agony", description = "Just when I thought another day was going to pass devoid of any joy, you brought me those marvelous Mudsnout Blossoms.\n\nFirst I will mix them down into a fine composite.  We'll then need Master Apothecary Faranell in the Undercity to apply his colloid of decay to it and then we'll be ready for some good fun indeed!\n\nHere, take this Mudsnout Composite and run it off to Master Faranell at once, $N.", objectives = "Take the Mudsnout Composite to Master Apothecary Faranell in the Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[514] = { title = "Letter to Stormpike", description = "I have a colleague in Ironforge who may be able to help decrypt this letter.  Go to the Library in the Hall of Explorers in Ironforge and speak with Prospector Stormpike.  Tell him I sent you and show him the letter.  If there's anyone north of Blackrock Spire who can read this, it is he.", objectives = "Take the Cleverly Encrypted Letter to Prospector Stormpike in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[515] = { title = "Elixir of Agony", description = "A mudsnout composite?  Absolutely brilliant!  Why didn't I think of that?\n\nLet me contribute my colloid of decay to this devilish brew.\n\nIn order to activate the contaminating agents in this mudsnout mixture, Lydon is going to need a strong troll's blood potion, as well as some daggerspine scales and torn fin eyes from the southern coast of Hillsbrad.  He'll know what to do once you've gathered him all the reagents.  And my, how anxious I am to hear how his experiment goes!", objectives = "Bring the Mudsnout Mixture, a Strong Troll's Blood Potion, 5 Daggerspine Scales and 5 Torn Fin Eyes to Apothecary Lydon in Tarren Mill.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[516] = { title = "Beren's Peril", description = "I have received reports that a group of undead are holing up to prepare for an attack against us. Armed with this information, we can turn the tables and attack them first, nipping their little plan in the bud.\n\nUnfortunately, my information is spotty, at best. They are reported to be hiding in a location known as Beren's Peril. The exact location is unknown, but it appears to be a cave in the hills, near a pocket of Dalaran wizards.\n\nI trust your resourcefulness. Find them, and put them down.", objectives = "Locate Beren's Peril, then kill 6 Ravenclaw Drudgers and 6 Ravenclaw Guardians, then return to Shadow Priest Allister at the Sepulcher.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[517] = { title = "Elixir of Agony", description = "This new elixir is finally ready to be tested.  But why let a perfectly good, highly contagious plague go to waste on a mere frog or dog?  Let's have us some true fun in the name of Lady Sylvanas.\n\nHead down to Dun Garok.  You know the barracks where those filthy little dwarves skitter about.  Steal me a keg of their Shindigger Stout.  Once I have that keg, you and I will have quite the party, $N.", objectives = "Bring a keg of Shindigger Stout to Apothecary Lydon in Tarren Mill.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[518] = { title = "The Crown of Will", description = "Mug'Thol and his Crushridge ogres have overrun the ruins of Alterac. It will be hard to inflict any serious punishment upon him without thinning out the ogres' numbers.\n\nAfter softening them up, we'll proceed.\n\nUnderstood? Good. Now go.", objectives = "Kill 14 Crushridge Maulers for Melisara in Tarren Mill.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[519] = { title = "The Crown of Will", description = "Targ, Muckrake, and Glommus are Mug'Thol's lieutenants. They are loyal to him, though who can say what drives an ogre to loyalty.\n\nBring me their heads, $n, and then all that will remain is to remove Mug'Thol's head, crown and all.", objectives = "Kill Targ, Muckrake, and Glommus and bring their heads to Melisara in Tarren Mill.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[520] = { title = "The Crown of Will", description = "With Mug'Thol's lieutenants dead, all that remains is to kill Mug'Thol and retrieve the Crown of Will. I have no doubt he'll be reluctant to part with it. Most likely expecting you, too, given the... departure... of his fellows.\n\nFind Mug'Thol, and deliver his head and the Crown to me. The Crushridge resistance will be at an end.", objectives = "Kill Mug'Thol, and return his head with the Crown of Will to Melisara in Tarren Mill.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[521] = { title = "The Crown of Will", description = "All that remains is to deliver the Crown of Will to Sharlindra in the Undercity. She will see that it is delivered to Lady Sylvanas. I would warn you against thinking to use it for your own purposes, $n, Mug'Thol's fate should be illustration enough.", objectives = "Deliver the Crown of Will to Sharlindra in the Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[522] = { title = "Assassin's Contract", description = "This is a contract for the assassination of Magistrate Henry Maleb.  It was sealed and stamped in red wax, using a distinctive signet ring.", objectives = "Bring the Assassin's Contract to Magistrate Maleb in Southshore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[523] = { title = "Baron's Demise", description = "The contract you recovered was signed by Baron Vardus, a noble of the former kingdom of Alterac, and one known for a cold heart and brutal practices.  I'm not surprised someone like the Baron was behind this.\n\nFind this man.  Find him, and bring him to justice.  He must be among the Syndicate haunts - perhaps at the ruins of Strahnbrad, or perhaps within the valley north of them.", objectives = "Bring the Head of Baron Vardus to Magistrate Maleb in Southshore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[524] = { title = "Elixir of Agony", description = "Next door the Deathguards are holding a few captured farmers hostage.  High Executor Darthalia suspected one of the military strategists from Stormwind to be hiding out amongst them.  Apparently the military chap was found dead in the Plaguelands last night.  Darthalia, always looking out for me, decided the prisoners would be left to my disposal.\n\nI think it's time we threw those farmers a party.  Sounds like a grand ol' time!\n\nPlace this tainted keg on the rug in their room.  Plagued brew for all!", objectives = "Place the Tainted Keg on the rug for the captured farmers.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[525] = { title = "Further Mysteries", description = "I decrypted the letter, but I don't know what to make of it.  You found this among thieves in the Alterac foothills?  Very strange...\n\nYou should take this to the magistrate of Southshore.  Although this letter is cryptic, his is the closest town to Alterac; if a threat is brewing, then he should know.", objectives = "Bring the Decrypted Letter to Magistrate Maleb in Southshore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[526] = { title = "Lightforge Ingots", description = "You might have found one lightforge ingot in that chest, but that's not enough to craft anything decent!\n\nYou should go back there and look for more.  Maybe the murlocs around that wrecked ship have lightforge ingots on them.", objectives = "Gather 5 lightforge ingots, then return to Glorin Steelbrow in the Wetlands.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
